import React, { ComponentPropsWithoutRef } from 'react';

import { mergeClasses } from '@libs/components/utils';

import { Tooltip } from '@components/Tooltip/Tooltip';

import './branch-diff.css';

/**
 * Prop types for BranchDiff
 */
export interface BranchDiffProps extends ComponentPropsWithoutRef<'div'> {
	/**
	 * Additional class names
	 */
	className?: string;
	/**
	 * Custom width in rems for the component. This will override the default.
	 */
	componentWidth?: number;
	/**
	 * Is the component in the process of loading?
	 */
	isLoading?: boolean;
	/**
	 * Text to be displayed in tooltip while component is loading.
	 */
	loadingText?: string;
	/**
	 * The number of commits the current branch is ahead of its upstream branch.
	 */
	numberAhead: number;
	/**
	 * A description for the `numberAhead` value.
	 */
	numberAheadDescription?: string;
	/**
	 * The number of commits the current branch is behind its upstream branch.
	 */
	numberBehind: number;
	/**
	 * A description for the `numberBehind` value.
	 */
	numberBehindDescription?: string;
}

/**
 * BranchDiff UI component
 */
export const BranchDiff = ({
	className,
	componentWidth,
	isLoading,
	loadingText = 'Loading...',
	numberAhead,
	numberAheadDescription = 'commits ahead of main',
	numberBehind,
	numberBehindDescription = 'commits behind main',
	...props
}: BranchDiffProps) => {
	// Set up classes.
	const baseClass = 'pds-branch-diff';
	const loadingClass = isLoading ? `${baseClass}--loading` : null;
	const pulseClass = isLoading ? 'pds-pulse' : null;

	// Handle componentWidth
	const computedWidth =
		componentWidth !== null && componentWidth > 0
			? `${componentWidth}rem`
			: '100%';

	// Ensure negative numbers are treated as 0
	let sanitizedNumberAhead = Math.max(0, numberAhead);
	let sanitizedNumberBehind = Math.max(0, numberBehind);

	// If loading, set both numbers to 1
	if (isLoading) {
		sanitizedNumberAhead = 1;
		sanitizedNumberBehind = 1;
	}

	// Determine the maximum commits
	const maxCommits = Math.max(sanitizedNumberAhead, sanitizedNumberBehind);

	// Calculate widths relative to the maximum
	let widthBehind =
		maxCommits > 0 ? (sanitizedNumberBehind / maxCommits) * 100 : 0;
	let widthAhead =
		maxCommits > 0 ? (sanitizedNumberAhead / maxCommits) * 100 : 0;

	// Enforce a minimum width of 10% for the smaller bar
	const minPercentage = 10;
	if (widthBehind < minPercentage) {
		widthBehind = minPercentage;
		widthAhead = 100 - minPercentage;
	} else if (widthAhead < minPercentage) {
		widthAhead = minPercentage;
		widthBehind = 100 - minPercentage;
	}

	// Prepare tooltip text
	const tooltipText = isLoading
		? loadingText
		: `${sanitizedNumberBehind} ${numberBehindDescription} & ${sanitizedNumberAhead} ${numberAheadDescription}`;

	// Render the output
	return (
		<div
			className={mergeClasses([baseClass, loadingClass, className ?? ''])}
			style={{ width: computedWidth }}
			{...props}
		>
			<Tooltip
				content={tooltipText}
				customTrigger={
					<div className={`${baseClass}__content`}>
						<div
							className={`${baseClass}__segment ${baseClass}__segment--behind`}
						>
							<div className={`${baseClass}__number`}>
								{!isLoading && sanitizedNumberBehind}
							</div>
							{sanitizedNumberBehind > 0 && (
								<div
									className={mergeClasses([
										`${baseClass}__line ${baseClass}__line--behind`,
										pulseClass,
									])}
									style={{ width: `${widthBehind}%` }}
								/>
							)}
						</div>
						<div
							className={`${baseClass}__segment ${baseClass}__segment--ahead`}
						>
							<div className={`${baseClass}__number`}>
								{!isLoading && sanitizedNumberAhead}
							</div>
							{sanitizedNumberAhead > 0 && (
								<div
									className={mergeClasses([
										`${baseClass}__line ${baseClass}__line--ahead`,
										pulseClass,
									])}
									style={{ width: `${widthAhead}%` }}
								/>
							)}
						</div>
					</div>
				}
				preferredPlacement='top'
			/>
		</div>
	);
};
