import { useRef, useState } from 'react';

import type { Placement } from '@floating-ui/react';
import {
	autoUpdate,
	flip,
	offset,
	safePolygon,
	shift,
	size,
	useClick,
	useDismiss,
	useFloating,
	useHover,
	useInteractions,
	useListNavigation,
	useRole,
	useTransitionStyles,
	useTypeahead,
} from '@floating-ui/react';

/**
 * Shared typeahead findMatch function.
 * Case-insensitive prefix matching on element text content.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const defaultFindMatch = (list: any[], typedString: string) => {
	const lowerTyped = typedString.toLowerCase();
	return list.find((item) => {
		const label =
			(item as unknown as HTMLElement)?.textContent?.trim().toLowerCase() ?? '';
		return label.startsWith(lowerTyped);
	});
};

export type DropdownRole = 'menu' | 'listbox' | 'dialog';
export type DropdownVariant = 'default' | 'input';

export interface UseDropdownOptions {
	/**
	 * Allow keyboard navigation to escape the list (move past first/last item).
	 * Useful for combobox inputs where focus should return to the input.
	 */
	allowEscape?: boolean;
	/**
	 * Enable click-to-toggle interaction via useClick.
	 * Set to false for combobox-type inputs where open/close is managed
	 * by input events (typing, focus) rather than a click toggle.
	 */
	enableClick?: boolean;
	/**
	 * Enable keyboard list navigation via useListNavigation.
	 * Set to false if keyboard nav is managed externally.
	 */
	enableListNavigation?: boolean;
	/**
	 * Enable shift middleware to keep the dropdown within viewport bounds.
	 * Set to false for inputs where the dropdown should align flush with the trigger.
	 */
	enableShift?: boolean;
	/**
	 * Enable transition animations on the dropdown panel.
	 */
	enableTransition?: boolean;
	/**
	 * Enable typeahead character search via useTypeahead.
	 */
	enableTypeahead?: boolean;
	/**
	 * Offset distance in pixels between the trigger and the dropdown panel.
	 * Ignored when variant is 'input' (uses dynamic offset based on placement).
	 */
	offsetValue?: number;
	/**
	 * Open the dropdown on hover (desktop navigation menus).
	 * Enables useHover with safePolygon.
	 */
	openOnHover?: boolean;
	/**
	 * Preferred placement of the dropdown panel relative to the trigger.
	 */
	placement?: Placement;
	/**
	 * ARIA role for the dropdown container.
	 */
	role?: DropdownRole;
	/**
	 * Index of the currently selected item. Used by typeahead to maintain
	 * selection context. Only needed for selection-style dropdowns (Select).
	 */
	selectedIndex?: number | null;
	/**
	 * Minimum clearance (px) shift maintains from the viewport edge — the
	 * "safe zone" a trigger closer than this is still nudged away from, even
	 * if the panel itself wouldn't actually overflow. Defaults to 24. Lower
	 * to 0 so shift only intervenes on genuine overflow, when a trigger
	 * sitting close to the edge (but not overflowing) needs to stay flush.
	 */
	shiftPadding?: number;
	/**
	 * Dropdown variant. 'input' applies input-specific positioning: dynamic
	 * offset based on placement direction and size constraints with min/max height.
	 * Use for Select, Combobox, and other input-attached dropdowns.
	 */
	variant?: DropdownVariant;
	/**
	 * Use virtual focus (aria-activedescendant) instead of roving tabindex.
	 * Appropriate for combobox-type inputs where focus must stay on the input.
	 */
	virtual?: boolean;
}

export interface UseDropdownReturn {
	/**
	 * Index of the currently active/focused item in the list.
	 */
	activeIndex: number | null;
	/**
	 * Styles to apply to the floating panel element.
	 */
	floatingStyles: ReturnType<typeof useFloating>['floatingStyles'];
	/**
	 * Props to spread on the floating panel element.
	 */
	getFloatingProps: ReturnType<typeof useInteractions>['getFloatingProps'];
	/**
	 * Props to spread on each item element.
	 */
	getItemProps: ReturnType<typeof useInteractions>['getItemProps'];
	/**
	 * Props to spread on the trigger/reference element.
	 */
	getReferenceProps: ReturnType<typeof useInteractions>['getReferenceProps'];
	/**
	 * Whether the floating panel should be mounted in the DOM
	 * (accounts for transition animations).
	 */
	isMounted: boolean;
	/**
	 * Whether the dropdown is currently open.
	 */
	isOpen: boolean;
	/**
	 * Ref array for list item DOM nodes (used by useListNavigation).
	 */
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	listRef: React.MutableRefObject<any[]>;
	/**
	 * Floating UI refs for the reference and floating elements.
	 */
	refs: ReturnType<typeof useFloating>['refs'];
	/**
	 * Set the active/focused item index.
	 */
	setActiveIndex: React.Dispatch<React.SetStateAction<number | null>>;
	/**
	 * Set the open state of the dropdown.
	 */
	setIsOpen: React.Dispatch<React.SetStateAction<boolean>>;
	/**
	 * Transition styles to apply to the floating panel element.
	 */
	transitionStyles: React.CSSProperties;
}

export const useDropdown = ({
	allowEscape = false,
	enableClick = true,
	enableListNavigation = true,
	enableShift = true,
	enableTransition = true,
	enableTypeahead = false,
	offsetValue = 0,
	openOnHover = false,
	placement = 'bottom-start',
	role = 'menu',
	selectedIndex = null,
	shiftPadding = 24,
	variant = 'default',
	virtual = false,
}: UseDropdownOptions = {}): UseDropdownReturn => {
	const [isOpen, setIsOpen] = useState(false);
	const [activeIndex, setActiveIndex] = useState<number | null>(null);
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	const listRef = useRef<any[]>([]);

	const isInputVariant = variant === 'input';

	// Build middleware based on variant.
	const buildMiddleware = () => {
		const middleware = [];

		// Offset — input variant uses dynamic offset, default uses static.
		if (isInputVariant) {
			middleware.push(
				offset(({ placement: p }) => (p.startsWith('top') ? 16 : 0)),
			);
		} else if (offsetValue > 0) {
			middleware.push(offset(offsetValue));
		}

		// Flip. `crossAxis: false` stops it from also flipping alignment
		// (bottom-start → bottom-end) when the floating element is narrow —
		// caused Datepicker's collapsed presets popover to render offset from
		// the trigger.
		middleware.push(flip({ crossAxis: false, padding: 24 }));

		// Shift — for bottom/top placements, floating-ui's "mainAxis" is horizontal (X).
		// Input variants disable mainAxis shifting so the panel always aligns with the
		// trigger instead of being bumped away from the viewport edge.
		if (enableShift) {
			middleware.push(
				shift({ padding: shiftPadding, mainAxis: !isInputVariant }),
			);
		}

		// Size — input variant matches reference width and adds minHeight; all variants cap maxHeight.
		middleware.push(
			size({
				apply({ availableHeight, elements, rects }) {
					if (elements.floating) {
						const styles: Record<string, string> = {
							maxHeight: `${availableHeight}px`,
						};
						if (isInputVariant) {
							styles.minHeight = 'var(--pds-spacing-3xl)';
							styles.minWidth = `${rects.reference.width}px`;
						}
						Object.assign(elements.floating.style, styles);
					}
				},
				padding: { top: 12, right: 24, bottom: 24, left: 24 },
			}),
		);

		return middleware;
	};

	// Floating UI positioning.
	const { context, floatingStyles, refs } = useFloating({
		open: isOpen,
		onOpenChange: setIsOpen,
		placement,
		whileElementsMounted: autoUpdate,
		middleware: buildMiddleware(),
		strategy: 'fixed',
	});

	// Interactions — all hooks called unconditionally (React rules of hooks),
	// toggled via `enabled` option where supported.
	const click = useClick(context, {
		enabled: enableClick,
		event: 'mousedown',
	});
	const dismiss = useDismiss(context);
	const roleInteraction = useRole(context, { role });
	const hover = useHover(context, {
		enabled: openOnHover,
		move: false,
		delay: { open: 100, close: 0 },
		handleClose: safePolygon({
			requireIntent: false,
			buffer: 10,
			blockPointerEvents: true,
		}),
	});
	const listNav = useListNavigation(context, {
		enabled: enableListNavigation,
		listRef,
		activeIndex,
		onNavigate: setActiveIndex,
		virtual,
		loop: true,
		allowEscape,
		focusItemOnHover: !virtual,
	});
	const typeahead = useTypeahead(context, {
		enabled: enableTypeahead,
		listRef,
		activeIndex,
		selectedIndex,
		onMatch: (index) => {
			if (isOpen) {
				setActiveIndex(index);
			} else {
				setIsOpen(true);
				setActiveIndex(index);
			}
		},
		findMatch: defaultFindMatch,
	});

	const { getFloatingProps, getItemProps, getReferenceProps } = useInteractions(
		[click, dismiss, roleInteraction, hover, listNav, typeahead],
	);

	// Transition styles.
	const { isMounted, styles: transitionStyles } = useTransitionStyles(
		context,
		enableTransition
			? {
					duration: { open: 300, close: 150 },
					initial: { opacity: 0 },
					open: { opacity: 1 },
					close: { opacity: 0 },
				}
			: {
					duration: 0,
				},
	);

	return {
		activeIndex,
		floatingStyles,
		getFloatingProps,
		getItemProps,
		getReferenceProps,
		isOpen,
		isMounted,
		listRef,
		refs,
		setActiveIndex,
		setIsOpen,
		transitionStyles,
	};
};
