import React, { ComponentPropsWithoutRef } from 'react';

import { mergeClasses } from '@libs/components/utils';

import './tally.css';

type TypeLabelsType = {
	critical?: string;
	info?: string;
	neutral?: string;
	success?: string;
	warning?: string;
};

/**
 * Prop types for Tally
 */
export interface TallyProps extends ComponentPropsWithoutRef<'div'> {
	/**
	 * Additional class names
	 */
	className?: string;
	/**
	 * Label text
	 */
	label: string | number;
	/**
	 * Size of the tally
	 */
	size?: 'xs' | 's' | 'm';
	/**
	 * Notification type
	 */
	type: 'neutral' | 'critical' | 'warning' | 'info' | 'success';
	/**
	 * Message type labels.
	 */
	typeLabels?: TypeLabelsType;
}

/**
 * Tally UI component
 */
export const Tally = ({
	className,
	label,
	size = 's',
	type = 'neutral',
	typeLabels = {
		info: 'Information',
		success: 'Success',
		warning: 'Warning',
		critical: 'Critical',
		neutral: '',
	},
	...props
}: TallyProps) => {
	// Set up classes.
	const baseClass = 'pds-tally';
	const colorClass = `${baseClass}--${type}`;
	const sizeClass = `${baseClass}--${size}`;

	// Label by type
	const messageTypeLabel = `${typeLabels[type]}: `;

	// Render the output
	return (
		<div
			className={mergeClasses([
				baseClass,
				colorClass,
				sizeClass,
				className ?? '',
			])}
			{...props}
		>
			<div className={`${baseClass}__label`}>
				<span className='visually-hidden'>{messageTypeLabel}</span>
				{label}
			</div>
		</div>
	);
};

Tally.displayName = 'Tally';
