// Input conditional field classes.
export const inputCommonClasses = {
	base: 'pds-input',
	disabled: 'pds-is-disabled',
	required: 'pds-is-required',
	error: 'pds-has-error',
	success: 'pds-has-success',
	readonly: 'pds-is-readonly',
};

// Process input width. Convert to rems.
export const getInputWidthStyle = (inputWidth: number) =>
	inputWidth ? { width: `${inputWidth / 16}rem` } : null;

// Function to strip http:// or https:// from input value
export const stripUrlProtocol = (value: string): string => {
	return value.replace(/^(https?:\/\/)/, '');
};

// Required Icon.
export const RequiredIcon = () => (
	<span className='pds-input-label__required'>
		<Icon
			className='pds-input-label__required-icon'
			iconName='asterisk'
			size='s'
		/>
	</span>
);

// InputLabel component.
interface InputLabelProps {
	/**
	 * Additional class names.
	 */
	className?: string;
	/**
	 * Is the field disabled?
	 */
	disabled: boolean;
	/**
	 * Input ID.
	 */
	id: string;
	/**
	 * Is the label a legend? Should be used when the input is a fieldset.
	 */
	isLegend?: boolean;
	/**
	 * Not a true `label`, but a description of the field.
	 * Used for inputs that have their label built into the element itself.
	 */
	isPseudoLabel?: boolean;
	/**
	 * Label text.
	 */
	label: string;
	/**
	 * Visual treatment of the label/legend text. `'default'` matches other
	 * form field labels (medium weight, tight spacing to the field) — use it
	 * when the fieldset is one of several inputs on a form. `'heading'` is
	 * semibold with more room below it, for cases where the group reads as
	 * its own section label rather than a form field among others (e.g. a
	 * filter panel's category groups).
	 */
	labelVariant?: 'default' | 'heading';
	/**
	 * Is the field required?
	 */
	required: boolean;
	/**
	 * Should the label be visible?
	 */
	showLabel: boolean;
	/**
	 * Optional tooltip text to display additional information.
	 */
	tooltipText?: string;
}

export const InputLabel = ({
	className,
	disabled,
	id,
	isLegend,
	isPseudoLabel,
	label,
	labelVariant = 'default',
	required,
	showLabel = true,
	tooltipText = null,
}: InputLabelProps) => {
	const labelClasses = mergeClasses([
		'pds-input-label',
		labelVariant === 'heading' ? 'pds-input-label--heading' : null,
		!showLabel ? 'visually-hidden' : null,
		className ?? '',
	]);

	const labelContent = (
		<>
			{label}
			{required && !disabled && <RequiredIcon />}
			{tooltipText && (
				<Tooltip
					content={tooltipText}
					triggerIcon='circleInfoSolid'
					triggerIconSize='s'
				/>
			)}
		</>
	);

	// If it's a legend, return a legend element.
	if (isLegend) {
		return (
			<legend className={labelClasses} id={`${id}-legend`}>
				{labelContent}
			</legend>
		);
	}

	// If it's a pseudo label, return a span element.
	if (isPseudoLabel) {
		return (
			<span className={labelClasses} id={`${id}-field-label`}>
				{labelContent}
			</span>
		);
	}

	// Otherwise, return a label element.
	return (
		<label className={labelClasses} htmlFor={id} id={`${id}-label`}>
			{labelContent}
		</label>
	);
};

// InputMessage component.
export const InputMessage = ({
	className,
	forInputGroup = false,
	hasValidationMessage,
	id,
	message,
	validationMessageHasDecorators,
	validationStatus,
}: {
	className?: string;
	forInputGroup?: boolean;
	hasValidationMessage?: boolean;
	id: string;
	message?: string | ReactNode;
	validationMessageHasDecorators?: boolean;
	validationStatus?: string;
}) => {
	const baseClass = 'pds-input-message';
	const statusClass =
		validationStatus && hasValidationMessage
			? `${baseClass}--${validationStatus}`
			: null;

	return (
		<div
			className={mergeClasses([baseClass, statusClass, className ?? ''])}
			id={forInputGroup ? `${id}__message-hidden` : `${id}__message`}
			role={validationStatus === 'error' ? 'alert' : null}
		>
			{validationMessageHasDecorators && validationStatus && (
				<InputPrefix variant={validationStatus as PrefixVariants} />
			)}
			<div className={`${baseClass}__text`}>{message}</div>
		</div>
	);
};

// InputPrefix component.
export type PrefixVariants = 'search' | 'error' | 'success' | 'filter';

const prefixIconVariants: Record<PrefixVariants, PDSIcon> = {
	search: 'magnifyingGlass',
	error: 'triangleExclamation',
	success: 'check',
	filter: 'barsFilter',
};

export const InputPrefix = ({ variant }: { variant: PrefixVariants }) => {
	const baseClass = 'pds-input-prefix';

	return (
		<div className={mergeClasses([baseClass, `${baseClass}--${variant}`])}>
			<Icon
				className={`${baseClass}__icon`}
				iconName={prefixIconVariants[variant]}
				size='m'
			/>
		</div>
	);
};

// SearchShortcut component.
export const SearchShortcut = ({
	inputId,
	shortcutLabel,
}: {
	inputId: string;
	shortcutLabel: string;
}) => {
	// The "/" shortcut is a desktop affordance. In the mobile presentation the
	// field is right there (and the shortcut sits inside the mobile menu overlay,
	// where "/" is blocked anyway), so drop both the hotkey and the visual hint.
	const isMobile = useIsMobile();

	// Handle search shortcut.
	const handleSearchShortcut = (e: KeyboardEvent) => {
		e.preventDefault();

		// The same input id can appear more than once in the DOM when the input is
		// rendered in multiple responsive containers that stay mounted and are
		// toggled by CSS (e.g. Navbar keeps both its mobile and desktop bars in the
		// DOM). getElementById returns the first match, which may be the hidden or
		// `inert` copy — and focus is a no-op inside an `inert` subtree. Focus the
		// first match that is actually rendered and interactive instead.
		const candidates = Array.from(
			document.querySelectorAll<HTMLElement>(`#${CSS.escape(inputId)}`),
		);
		const target =
			candidates.find(
				(el) => el.getClientRects().length > 0 && !el.closest('[inert]'),
			) ?? candidates[0];

		target?.focus();
	};

	// Set up search shortcut hotkey. useKeyboardShortcut ignores form fields by
	// default (so typing "/" in another input never steals focus) and
	// auto-suppresses while an overlay is open, so we only gate on the mobile
	// presentation here.
	useKeyboardShortcut('/', handleSearchShortcut, {
		enabled: !isMobile,
	});

	// No shortcut hint in the mobile presentation.
	if (isMobile) {
		return null;
	}

	return (
		<div className='pds-input-search-shortcut'>
			<span className='visually-hidden'>{shortcutLabel}</span>
			<Icon iconName='slashForward' size='s' />
		</div>
	);
};

// ClearButton component.
export const ClearButton = ({
	clearLabel,
	handleClearInput,
	id,
}: {
	clearLabel: string;
	handleClearInput: MouseEventHandler<HTMLButtonElement>;
	id: string;
}) => {
	return (
		<button
			aria-controls={id}
			className='pds-input-clear-button'
			onClick={handleClearInput}
			title={clearLabel}
			type='button'
		>
			<Icon iconName='xmark' size='m' />
		</button>
	);
};

// CharacterCounter component.
export const CharacterCounter = ({
	currentLength,
	id,
	maxLength,
	overLimitMessage = 'Character limit exceeded by',
}: {
	currentLength: number;
	id: string;
	maxLength: number;
	overLimitMessage: string;
}) => {
	const isOverLimit = currentLength > maxLength;
	const overLimitCount = currentLength - maxLength;

	const baseClass = 'pds-input-character-counter';
	const overLimitClass = isOverLimit ? `${baseClass}--overLimit` : null;

	return (
		<div
			className={mergeClasses([baseClass, overLimitClass])}
			id={`${id}__counter`}
		>
			{currentLength}/{maxLength}
			<span aria-live='polite' className='visually-hidden'>
				{isOverLimit && `${overLimitMessage} ${overLimitCount}`}
			</span>
		</div>
	);
};

// HiddenLabel component.
export const HiddenLabel = ({ label, ...props }) => (
	<span className='visually-hidden' {...props}>
		{label}
	</span>
);

// Select option group component.
export const isOptionGroup = (
	option: SelectOptionType | SelectOptionGroupType,
): option is SelectOptionGroupType => {
	return 'options' in option;
};

// Select option component.
// For use with Combobox and Select components.
interface SelectOptionProps extends ComponentPropsWithoutRef<'li'> {
	children?: ReactNode;
	className?: string;
	isActive?: boolean;
}

export const SelectOption = forwardRef(
	(
		{ children, className, isActive, ...props }: SelectOptionProps,
		ref: Ref<HTMLLIElement>,
	) => {
		const id = useId();

		const activeClass = isActive ? 'pds-dropdown__item--active' : null;

		return (
			<li
				ref={ref}
				aria-selected={isActive}
				className={mergeClasses([
					'pds-dropdown__item',
					activeClass,
					className ?? '',
				])}
				id={id}
				role='option'
				{...props}
			>
				{children}
			</li>
		);
	},
);
