import React, {
	ComponentPropsWithoutRef,
	ElementType,
	isValidElement,
	ReactNode,
	useState,
} from 'react';

import hashSum from 'hash-sum';

import { mergeClasses } from '@libs/components/utils';

import { Icon } from '@components/icons/Icon/Icon';

import './tag.css';

export const tagColors = [
	'orange',
	'stone',
	'gold',
	'lime',
	'mint',
	'teal',
	'sky',
	'slate',
	'indigo',
	'purple',
	'magenta',
	'rose',
	'red',
] as const;

type TagMutedColor = (typeof tagColors)[number];

// Solid hues — saturated variants of the muted palette with no semantic
// meaning of their own. Unlike the status-solid colors below, they're safe to
// include in auto-assignment.
export const tagSolidHueColors = [
	'orange-solid',
	'teal-solid',
	'indigo-solid',
	'magenta-solid',
	'rose-solid',
	'gold-solid',
	'lime-solid',
	'sky-solid',
	'slate-solid',
] as const;

type TagSolidHueColor = (typeof tagSolidHueColors)[number];

// Status-solid colors carry semantic meaning elsewhere in the system (status
// chips, StatusBadge, etc.), so they must always be passed explicitly and
// never participate in auto-assignment.
export const tagSolidStatusColors = [
	'success-solid',
	'warning-solid',
	'critical-solid',
	'info-solid',
	'discovery-solid',
] as const;

type TagSolidStatusColor = (typeof tagSolidStatusColors)[number];

export const tagSolidColors = [
	...tagSolidHueColors,
	...tagSolidStatusColors,
] as const;

type TagSolidColor = TagSolidHueColor | TagSolidStatusColor;

export type TagColor = TagMutedColor | TagSolidColor;

// The pool auto-assignment hashes into — the 14 muted colors plus the 5
// non-semantic solid hues. Status-solid colors are excluded so a randomly
// hashed label can never read as an error/warning/etc.
const tagAutoAssignColors = [...tagColors, ...tagSolidHueColors] as const;

export type TagSize = 'xs' | 's' | 'm';

interface TagProps extends ComponentPropsWithoutRef<'div'> {
	/**
	 * Additional class names
	 */
	className?: string;
	/**
	 * Should the tag be removable?
	 */
	isRemovable?: boolean;
	/**
	 * Should the tag be a link? If yes, provide a link element.
	 */
	linkContent?: ReactNode;
	/**
	 * Function to execute when the tag is removed.
	 */
	onRemove?: () => void;
	/**
	 * Label for the remove button. Tag text will be appended to this label.
	 */
	removeLabel?: string;
	/**
	 * Size of the tag.
	 */
	size?: TagSize;
	/**
	 * Tag color. Will use random color if not selected.
	 */
	tagColor?: TagColor;
	/**
	 * Tag text
	 */
	tagLabel: string;
	/**
	 * Maximum number of characters before truncation. Set to 0 to disable
	 * truncation entirely. Defaults to 20. Most use cases should keep the
	 * default, especially in multi-tag contexts.
	 */
	truncationLength?: number;
}

// Creates consistent color based on the content on children
const labelToColor = (tagLabel: string): TagColor => {
	const pos = parseInt(hashSum(tagLabel), 16);
	const color: TagColor = tagAutoAssignColors[pos % tagAutoAssignColors.length];
	return color;
};

// Function to truncate strings
const truncateString = (str: string, maxLength: number) => {
	if (str.length > maxLength) {
		return str.slice(0, maxLength) + ' ...';
	} else {
		return str;
	}
};

/**
 * Tag UI component
 */
export const Tag = ({
	className,
	isRemovable,
	linkContent,
	onRemove,
	removeLabel = 'Remove tag',
	size = 's',
	tagColor,
	tagLabel,
	truncationLength = 18,
	...props
}: TagProps) => {
	// Set up state.
	const [visible, setVisible] = useState(true);

	// Set up classes.
	const baseClass = 'pds-tag';
	const colorClass = tagColor
		? `${baseClass}--${tagColor}`
		: `${baseClass}--${labelToColor(tagLabel)}`;
	const sizeClass = `${baseClass}--${size}`;
	const visibleClass = visible ? null : 'pds-tag--hide';

	//  Remove the tag, if it is removable.
	const removeElement = () => {
		setVisible((prev) => !prev);
	};

	// Deconstruct linkContent so we can wrap it around the tag.
	let TagElement: string | ElementType;
	let linkAttribute: string | null;
	let linkUrl: string | null;

	if (linkContent && !isRemovable && isValidElement(linkContent)) {
		TagElement = linkContent.type;
		const props = linkContent.props as { href?: string; to?: string };
		linkAttribute = props.href ? 'href' : 'to';
		linkUrl = linkAttribute === 'href' ? props.href : props.to;
	} else {
		TagElement = 'span';
		linkAttribute = null;
		linkUrl = null;
	}

	// Render the output.
	return (
		<TagElement
			className={mergeClasses([
				baseClass,
				colorClass,
				sizeClass,
				visibleClass,
				className,
			])}
			href={linkAttribute === 'href' ? linkUrl : null}
			to={linkAttribute === 'to' ? linkUrl : null}
			{...props}
		>
			<span className={`${baseClass}__label`} title={tagLabel}>
				{truncationLength > 0
					? truncateString(tagLabel, truncationLength)
					: tagLabel}
			</span>
			{isRemovable ? (
				<button
					aria-label={`${removeLabel}: ${tagLabel}`}
					className={`${baseClass}__remove`}
					onClick={() => {
						removeElement();
						onRemove();
					}}
					type='button'
				>
					<Icon
						className={`${baseClass}__remove-icon`}
						iconName='xmark'
						size='m'
					/>
				</button>
			) : null}
		</TagElement>
	);
};
