import React, {
	ComponentPropsWithoutRef,
	createContext,
	ReactNode,
	useContext,
} from 'react';

import { mergeClasses } from '@libs/components/utils';

import {
	useDropdown,
	UseDropdownOptions,
	UseDropdownReturn,
} from '@utilities/hooks/useDropdown';

import { Icon } from '@components/icons/Icon/Icon';

import './dropdown.css';

// Context

const DropdownContext = createContext<UseDropdownReturn | null>(null);

const useDropdownContext = () => {
	const context = useContext(DropdownContext);
	if (!context) {
		throw new Error(
			'Dropdown sub-components must be used within a <Dropdown> provider.',
		);
	}
	return context;
};

// Dropdown (root)

export interface DropdownProps extends UseDropdownOptions {
	/**
	 * Dropdown sub-components (Trigger, Panel, etc.).
	 */
	children?: ReactNode;
	/**
	 * Additional class names for the root wrapper.
	 */
	className?: string;
	/**
	 * Use inline-block display instead of block.
	 * Useful when the dropdown trigger should size to its content
	 * (e.g., UserMenu, MenuButton) rather than fill the parent width.
	 */
	inline?: boolean;
}

/**
 * Root Dropdown component. Provides dropdown context to sub-components.
 */
export const Dropdown = ({
	children,
	className,
	inline,
	...options
}: DropdownProps) => {
	const dropdown = useDropdown(options);
	const baseClass = 'pds-dropdown';
	const inlineClass = inline ? `${baseClass}--inline` : null;

	return (
		<DropdownContext.Provider value={dropdown}>
			<div className={mergeClasses([baseClass, inlineClass, className ?? ''])}>
				{children}
			</div>
		</DropdownContext.Provider>
	);
};

// Dropdown.Trigger

export interface DropdownTriggerProps extends ComponentPropsWithoutRef<'button'> {
	/**
	 * Trigger content (label text, icon, etc.).
	 */
	children?: ReactNode;
	/**
	 * Additional class names.
	 */
	className?: string;
	/**
	 * Show a directional icon on the trigger that indicates the dropdown can be expanded.
	 */
	showTriggerIcon?: boolean;
}

const DropdownTrigger = ({
	children,
	className,
	showTriggerIcon = false,
	...props
}: DropdownTriggerProps) => {
	const { getReferenceProps, refs } = useDropdownContext();
	const baseClass = 'pds-dropdown';

	return (
		<button
			ref={refs.setReference}
			className={mergeClasses([`${baseClass}__trigger`, className ?? ''])}
			type='button'
			{...getReferenceProps()}
			{...props}
		>
			{children}
			{showTriggerIcon && (
				<Icon
					className={`${baseClass}__trigger-icon`}
					iconName='angleDown'
					size='s'
				/>
			)}
		</button>
	);
};

// Dropdown.Panel

export interface DropdownPanelProps extends ComponentPropsWithoutRef<'ul'> {
	/**
	 * Panel content (Items, Headings, Separators, Filter, etc.).
	 */
	children?: ReactNode;
	/**
	 * Additional class names.
	 */
	className?: string;
}

const DropdownPanel = ({
	children,
	className,
	...props
}: DropdownPanelProps) => {
	const {
		floatingStyles,
		getFloatingProps,
		isMounted,
		refs,
		transitionStyles,
	} = useDropdownContext();
	const baseClass = 'pds-dropdown';

	if (!isMounted) {
		return null;
	}

	return (
		<ul
			ref={refs.setFloating}
			className={mergeClasses([`${baseClass}__panel`, className ?? ''])}
			style={{
				...floatingStyles,
				...transitionStyles,
			}}
			{...getFloatingProps()}
			{...props}
		>
			{children}
		</ul>
	);
};

// Dropdown.Item

export interface DropdownItemProps extends ComponentPropsWithoutRef<'li'> {
	/**
	 * Item content — label text, or a link element for navigation items.
	 */
	children?: ReactNode;
	/**
	 * Additional class names.
	 */
	className?: string;
	/**
	 * Close the dropdown when this item is clicked (default: true).
	 * Set to false for items that shouldn't dismiss the menu — e.g. one that
	 * opens a submenu or triggers a multi-step flow.
	 */
	closeOnSelect?: boolean;
	/**
	 * Secondary text displayed below the label.
	 */
	description?: ReactNode;
	/**
	 * Disabled state.
	 */
	disabled?: boolean;
	/**
	 * Leading content — PDSIcon name, or custom ReactNode (Avatar, etc.).
	 */
	icon?: ReactNode;
	/**
	 * Index of this item in the list (required for keyboard navigation).
	 */
	index: number;
	/**
	 * Selected or current state.
	 */
	isActive?: boolean;
	/**
	 * Destructive action styling.
	 */
	isCritical?: boolean;
	/**
	 * Trailing content — check icon, lock icon, or custom ReactNode.
	 */
	trailingIcon?: ReactNode;
}

const DropdownItem = ({
	children,
	className,
	closeOnSelect = true,
	description,
	disabled,
	icon,
	index,
	isActive,
	isCritical,
	onClick,
	onKeyDown,
	trailingIcon,
	...props
}: DropdownItemProps) => {
	const { activeIndex, getItemProps, listRef, setIsOpen } =
		useDropdownContext();
	const baseClass = 'pds-dropdown';
	const isFocused = activeIndex === index;

	const focusedClass = isFocused ? `${baseClass}__item--focused` : null;
	const activeClass = isActive ? `${baseClass}__item--active` : null;
	const criticalClass = isCritical ? `${baseClass}__item--critical` : null;
	const disabledClass = disabled ? `${baseClass}__item--disabled` : null;

	const selectItem = (event: React.SyntheticEvent<HTMLElement>) => {
		onClick?.(event as unknown as React.MouseEvent<HTMLLIElement>);
		if (closeOnSelect) {
			setIsOpen(false);
		}
	};

	return (
		<li
			ref={(node) => {
				listRef.current[index] = node;
			}}
			aria-disabled={disabled || undefined}
			className={mergeClasses([
				`${baseClass}__item`,
				focusedClass,
				activeClass,
				criticalClass,
				disabledClass,
				className ?? '',
			])}
			role='menuitem'
			tabIndex={isFocused ? 0 : -1}
			{...getItemProps({
				onClick: disabled ? undefined : selectItem,
				onKeyDown: disabled
					? undefined
					: (event: React.KeyboardEvent<HTMLElement>) => {
							// Enter/Space activate the row (menuitem activation),
							// which getItemProps does not do for <li> items.
							if (event.key === ' ' || event.key === 'Enter') {
								event.preventDefault();
								selectItem(event);
							}
							onKeyDown?.(event as React.KeyboardEvent<HTMLLIElement>);
						},
			})}
			{...props}
		>
			<span className={`${baseClass}__item-content`}>
				{icon && <span className={`${baseClass}__item-icon`}>{icon}</span>}
				<span className={`${baseClass}__item-label`}>
					{children}
					{description && (
						<span className={`${baseClass}__item-description`}>
							{description}
						</span>
					)}
				</span>
			</span>
			{trailingIcon && (
				<span className={`${baseClass}__item-trailing`}>{trailingIcon}</span>
			)}
		</li>
	);
};

// Dropdown.CheckboxItem

export interface DropdownCheckboxItemProps extends Omit<
	ComponentPropsWithoutRef<'li'>,
	'onChange'
> {
	/**
	 * Checked state of the item.
	 */
	checked?: boolean;
	/**
	 * Item label content.
	 */
	children?: ReactNode;
	/**
	 * Additional class names.
	 */
	className?: string;
	/**
	 * Secondary text displayed below the label.
	 */
	description?: ReactNode;
	/**
	 * Disabled state.
	 */
	disabled?: boolean;
	/**
	 * Partial/mixed state — renders a dash instead of a check.
	 */
	indeterminate?: boolean;
	/**
	 * Index of this item in the list (required for keyboard navigation).
	 */
	index: number;
	/**
	 * Callback fired when the item is toggled, with the next checked value.
	 */
	onCheckedChange?: (checked: boolean) => void;
}

const DropdownCheckboxItem = ({
	checked = false,
	children,
	className,
	description,
	disabled,
	indeterminate = false,
	index,
	onCheckedChange,
	onClick,
	onKeyDown,
	...props
}: DropdownCheckboxItemProps) => {
	const { activeIndex, getItemProps, listRef } = useDropdownContext();
	const baseClass = 'pds-dropdown';
	const isFocused = activeIndex === index;

	const focusedClass = isFocused ? `${baseClass}__item--focused` : null;
	const disabledClass = disabled ? `${baseClass}__item--disabled` : null;

	const boxClass = mergeClasses([
		`${baseClass}__checkbox-box`,
		checked && !indeterminate ? `${baseClass}__checkbox-box--checked` : null,
		indeterminate ? `${baseClass}__checkbox-box--indeterminate` : null,
	]);

	return (
		<li
			ref={(node) => {
				listRef.current[index] = node;
			}}
			aria-checked={indeterminate ? 'mixed' : checked}
			aria-disabled={disabled || undefined}
			className={mergeClasses([
				`${baseClass}__item`,
				`${baseClass}__checkbox-item`,
				focusedClass,
				disabledClass,
				className ?? '',
			])}
			role='menuitemcheckbox'
			tabIndex={isFocused ? 0 : -1}
			{...getItemProps({
				onClick: disabled
					? undefined
					: (event) => {
							onCheckedChange?.(!checked);
							onClick?.(event as React.MouseEvent<HTMLLIElement>);
						},
				onKeyDown: disabled
					? undefined
					: (event) => {
							// Space/Enter toggle the row (menuitemcheckbox activation),
							// which getItemProps does not do for <li> items.
							if (event.key === ' ' || event.key === 'Enter') {
								event.preventDefault();
								onCheckedChange?.(!checked);
							}
							onKeyDown?.(event as React.KeyboardEvent<HTMLLIElement>);
						},
			})}
			{...props}
		>
			<span className={`${baseClass}__item-content`}>
				<span aria-hidden='true' className={boxClass}>
					{indeterminate ? (
						<svg
							className={`${baseClass}__checkbox-icon`}
							fill='currentColor'
							height='12'
							viewBox='0 0 12 12'
							width='12'
							xmlns='http://www.w3.org/2000/svg'
						>
							<rect height='2' rx='1' width='8' x='2' y='5' />
						</svg>
					) : (
						checked && (
							<svg
								className={`${baseClass}__checkbox-icon`}
								fill='currentColor'
								height='12'
								viewBox='0 0 12 12'
								width='12'
								xmlns='http://www.w3.org/2000/svg'
							>
								<path d='M9.85474 3.64666C10.1032 3.32078 10.0258 2.86817 9.67727 2.63583C9.32878 2.4035 8.84476 2.47591 8.5963 2.80179L4.8694 7.65977L3.32056 6.21143C3.01724 5.9278 2.52677 5.9278 2.22669 6.21143C1.9266 6.49506 1.92337 6.9537 2.22346 7.23734L4.41765 9.28916C4.57899 9.44003 4.80164 9.51546 5.02751 9.49736C5.25338 9.47925 5.4599 9.37063 5.59219 9.19864L9.85151 3.64666H9.85474Z' />
							</svg>
						)
					)}
				</span>
				<span className={`${baseClass}__item-label`}>
					{children}
					{description && (
						<span className={`${baseClass}__item-description`}>
							{description}
						</span>
					)}
				</span>
			</span>
		</li>
	);
};

// Dropdown.Heading

export interface DropdownHeadingProps extends ComponentPropsWithoutRef<'li'> {
	/**
	 * Heading text.
	 */
	children?: ReactNode;
	/**
	 * Additional class names.
	 */
	className?: string;
}

const DropdownHeading = ({
	children,
	className,
	...props
}: DropdownHeadingProps) => {
	const baseClass = 'pds-dropdown';

	return (
		<li
			className={mergeClasses([`${baseClass}__heading`, className ?? ''])}
			role='presentation'
			{...props}
		>
			{children}
		</li>
	);
};

