// Dropdown.Filter

export type DropdownFilterIcon = 'filter' | 'none' | 'search';

export interface DropdownFilterProps extends ComponentPropsWithoutRef<'li'> {
	/**
	 * Additional class names.
	 */
	className?: string;
	/**
	 * Icon to display inside the filter input.
	 */
	filterIcon?: DropdownFilterIcon;
	/**
	 * Label for the filter input (screen readers).
	 */
	label?: string;
	/**
	 * Text shown when no items match the filter.
	 */
	noResultsText?: string;
	/**
	 * Callback when the filter value changes.
	 */
	onFilterChange?: (value: string) => void;
	/**
	 * Placeholder text for the filter input.
	 */
	placeholder?: string;
	/**
	 * Whether to show the "no results" message.
	 */
	showNoResults?: boolean;
}

const filterIconNames = {
	filter: 'barsFilter',
	search: 'magnifyingGlass',
} as const;

const DropdownFilter = ({
	className,
	filterIcon = 'search',
	label = 'Filter items',
	noResultsText = 'No results found',
	onFilterChange,
	placeholder = 'Filter items...',
	showNoResults = false,
	...props
}: DropdownFilterProps) => {
	const baseClass = 'pds-dropdown';
	const hasIcon = filterIcon !== 'none';

	return (
		<li
			className={mergeClasses([`${baseClass}__filter`, className ?? ''])}
			role='presentation'
			{...props}
		>
			<div className={`${baseClass}__filter-wrapper`}>
				{hasIcon && (
					<Icon
						className={`${baseClass}__filter-icon`}
						iconName={filterIconNames[filterIcon]}
						size='s'
					/>
				)}
				<input
					aria-label={label}
					className={`${baseClass}__filter-input`}
					onChange={(e) => onFilterChange?.(e.target.value)}
					placeholder={placeholder}
					type='search'
				/>
			</div>
			{showNoResults && (
				<p className={`${baseClass}__no-results`}>{noResultsText}</p>
			)}
		</li>
	);
};

