import { Children, Fragment, isValidElement } from 'react';

// Function to collect all descendants of an element.
export const getDescendants = (node, collect) => {
	// Check for children first.
	if (!node?.childNodes) {
		return;
	}

	// Collect all children.
	let i;
	collect = collect || [];
	for (i = 0; i < node.childNodes.length; i++) {
		collect.push(node.childNodes[i]);
		getDescendants(node.childNodes[i], collect);
	}
	return collect;
};

// Function to initiate slots from a children prop.
export const initiateSlots = (children) => {
	const slots = {};
	const unslotted = [];

	Children.forEach(children, (child) => {
		if (isValidElement(child)) {
			const slotName = child.props.slot;
			if (slotName) {
				if (slots[slotName]) {
					slots[slotName].push(child);
				} else {
					slots[slotName] = [child];
				}
			} else {
				unslotted.push(child);
			}
		} else {
			// Handle non-React elements (strings, numbers, etc.)
			unslotted.push(child);
		}
	});

	// Add unslotted children to the slots object with a special key
	if (unslotted.length > 0) {
		slots['__unslotted'] = unslotted;
	}

	return slots;
};

/**
 * Function to check whether a set of slotted elements has anything worth
 * rendering a slot wrapper for.
 *
 * Lets a component skip an optional slot's padded wrapper when the caller
 * conditionally rendered nothing into it, e.g.
 * `<div slot="footer">{condition && <X />}</div>` with a falsy `condition`,
 * which would otherwise leave an empty padded strip behind.
 *
 * Only plain host elements and fragments are unwrapped and judged by their
 * children, since those are the shapes used as a conditional pass-through. A
 * component instance is treated as content in itself — its visible output may
 * come from any prop (`Button`'s `label`, `ButtonLink`'s `linkContent`), so
 * its `children` say nothing about whether it renders.
 */
export const hasRenderableSlotContent = (slotElements) =>
	Array.isArray(slotElements) &&
	slotElements.some((element) => {
		// `initiateSlots` only ever assigns elements to a named slot.
		if (!isValidElement(element)) {
			return false;
		}

		if (typeof element.type !== 'string' && element.type !== Fragment) {
			return true;
		}

		const slotChildren = element.props.children;
		return Array.isArray(slotChildren)
			? slotChildren.some(Boolean)
			: Boolean(slotChildren);
	});

// Function to merge css classes
export const mergeClasses = (styles) =>
	styles.join(' ').trim().replace(/\s+/g, ' ');

/**
 * Function to validate if image src is valid, restricts base64 to data image types and excludes svg + xml
 */
export const isValidImageSrc = (uri) => {
	if (!uri) return false;

	if (!uri.startsWith('data:')) return true;

	const regex =
		/^data:image\/(png|jpeg|jpg|gif|bmp|webp);base64,[A-Za-z0-9+/]+=*$/;
	return regex.test(uri);
};
