import Prism from 'prismjs/components/prism-core';

// prismjs's language extensions (imported after this module) reference a
// bare, undeclared `Prism` identifier and expect it to resolve via the
// global object. prism-core only publishes itself to `window.Prism`, so
// under Node.js SSR (e.g. Next.js production builds, which have no
// `window`) that global is never set and the language extensions throw
// `ReferenceError: Prism is not defined`. Publish it ourselves so it
// resolves in every environment. This must live in its own module: ES
// module imports fully evaluate before any of the importing file's own
// top-level code runs, so this assignment has to happen as part of this
// module's evaluation to occur before the language extensions' imports.
if (typeof globalThis !== 'undefined') {
	(globalThis as typeof globalThis & { Prism?: typeof Prism }).Prism = Prism;
}

export default Prism;
