import React, { ComponentPropsWithoutRef } from 'react';

import { mergeClasses } from '@libs/components/utils';
import { Display, IconSize } from '@libs/types/custom-types';

import {
	customIcons,
	iconData,
	iconList,
	type PDSIconName,
} from './generated-icon-data';

import './icon.css';

/**
 * PDS Icon type - union of all available icon names.
 */
export type PDSIcon = PDSIconName;

// Re-export for external consumers (Storybook, etc.)
export { iconList };

/**
 * Icon component prop types.
 */
export interface IconProps extends ComponentPropsWithoutRef<'svg'> {
	/**
	 * Display value
	 */
	display?: Display;
	/**
	 * Which icon to render
	 */
	iconName: PDSIcon;
	/**
	 * Which size of icon to render
	 */
	size?: IconSize;
	/**
	 * Vertical align value
	 */
	verticalAlign?: string;
}

/**
 * A component used to display an icon.
 */
export const Icon = ({
	className,
	display = 'inline-block',
	iconName,
	size = 'l',
	style,
	verticalAlign = 'middle',
	...props
}: IconProps) => {
	const baseClass = 'pds-icon';
	const iconClasses = `${baseClass} ${baseClass}--${size} ${baseClass}--${iconName}`;
	const data = iconData[iconName];
	const viewBox = `0 0 ${data.width} ${data.height}`;

	// Check if this is a complex custom icon (e.g. nextJs with masks/gradients)
	const customIcon =
		iconName in customIcons
			? customIcons[iconName as keyof typeof customIcons]
			: null;

	// Determine icon content
	let iconContent: React.ReactNode;

	if (customIcon?.type === 'complex') {
		iconContent = customIcon.render();
	} else {
		const pathData =
			customIcon?.type === 'path' ? customIcon.svgPathData : data.svgPathData;

		iconContent = Array.isArray(pathData) ? (
			pathData.map((d, i) => <path key={i} d={d} fill='currentColor' />)
		) : (
			<path d={pathData} fill='currentColor' />
		);
	}

	return (
		<svg
			aria-hidden='true'
			className={mergeClasses([iconClasses, className ?? ''])}
			fill='none'
			focusable='false'
			preserveAspectRatio='xMidYMid meet'
			role='img'
			style={{
				display: display,
				verticalAlign: verticalAlign,
				...style,
			}}
			viewBox={viewBox}
			xmlns='http://www.w3.org/2000/svg'
			{...props}
		>
			{iconContent}
		</svg>
	);
};
