import React, { ComponentPropsWithoutRef, ReactNode, useState } from 'react';

import {
	autoUpdate,
	flip,
	FloatingPortal,
	offset,
	Placement,
	shift,
	useDismiss,
	useFloating,
	useFocus,
	useHover,
	useInteractions,
	useRole,
	useTransitionStyles,
} from '@floating-ui/react';
import { Z_INDEX_MAX } from '@pantheon-systems/pds-design-tokens/build/js/variables.global.js';

import { mergeClasses } from '@libs/components/utils';
import { FuiOffset } from '@libs/types/custom-types';

import { Icon } from '@components/icons/Icon/Icon';

import './tooltip.css';

interface TooltipProps extends ComponentPropsWithoutRef<'div'> {
	/**
	 * Additional class names
	 */
	className?: string;
	/**
	 * Text to display in tooltip container.
	 */
	content: string;
	/**
	 * String or HTML content to use as the trigger instead of an icon. Leave null to use the icon.
	 */
	customTrigger?: ReactNode;
	/**
	 * When true, the tooltip will not show on focus — only on hover.
	 */
	disableFocusTrigger?: boolean;
	/**
	 * The spacing between the trigger and the tooltip in pixels. Use the default value (in most cases) when using an icon trigger.
	 */
	offsetValue?: FuiOffset;
	/**
	 * The preferred placement of the tooltip relative to the trigger.
	 */
	preferredPlacement?: Placement;
	/**
	 * The accessible text for the trigger. Only necessary when the trigger is an icon.
	 */
	triggerAccessibleText?: string;
	/**
	 * Icon to trigger tooltip
	 */
	triggerIcon?:
		| 'circleExclamation'
		| 'circleExclamationSolid'
		| 'circleInfo'
		| 'circleInfoSolid'
		| 'circleQuestion'
		| 'circleQuestionSolid';
	/**
	 * Color of the trigger icon. Uses PDS default text color options.
	 */
	triggerIconColor?: 'default' | 'default-secondary' | 'critical';
	/**
	 * Size of the trigger icon. Uses PDS Icon sizing.
	 */
	triggerIconSize?: 's' | 'm' | 'l';
	/**
	 * Z-index value for the tooltip container. In most cases, the default value should be retained.
	 */
	zIndex?: number;
}

/**
 * Tooltip UI component
 */
export const Tooltip = ({
	className,
	content,
	customTrigger = null,
	disableFocusTrigger = false,
	offsetValue = 6,
	preferredPlacement = 'top',
	triggerAccessibleText = 'Show more information',
	triggerIcon = 'circleInfo',
	triggerIconColor = 'default',
	triggerIconSize = 'm',
	zIndex = Z_INDEX_MAX,
	...props
}: TooltipProps) => {
	// Set up state.
	const [isOpen, setIsOpen] = useState(false);

	// Get type of custom trigger.
	const triggerType = typeof customTrigger;

	// Set up classes.
	const baseClass = 'pds-tooltip';
	const customTriggerClasses = mergeClasses([
		`${baseClass}__trigger-custom`,
		triggerType === 'string' ? `${baseClass}__trigger-text` : null,
	]);
	const iconTriggerClasses = mergeClasses([
		`${baseClass}__trigger`,
		`${baseClass}__trigger--${triggerIconColor}`,
	]);

	// FUI config.
	const { context, floatingStyles, refs } = useFloating({
		placement: preferredPlacement,
		open: isOpen,
		onOpenChange: setIsOpen,
		middleware: [offset(offsetValue), flip(), shift()],
		whileElementsMounted: autoUpdate,
		strategy: 'fixed',
	});

	const hover = useHover(context, {
		restMs: 300,
		delay: { open: 100, close: 0 },
		move: false,
	});
	const focus = useFocus(context, { enabled: !disableFocusTrigger });
	const dismiss = useDismiss(context);
	const role = useRole(context, { role: 'tooltip' });

	const { getFloatingProps, getReferenceProps } = useInteractions([
		hover,
		focus,
		dismiss,
		role,
	]);

	// Only keep the tooltip container mounted while open/transitioning so it
	// can't sit permanently in document.body's layout flow when closed.
	const { isMounted, styles: transitionStyles } = useTransitionStyles(context, {
		duration: { open: 0, close: 300 },
		initial: { opacity: 0 },
		open: { opacity: 1 },
		close: { opacity: 0 },
	});

	// Render the output
	return (
		<div className={mergeClasses([baseClass, className ?? ''])} {...props}>
			{customTrigger ? (
				<span
					ref={refs.setReference}
					className={customTriggerClasses}
					{...getReferenceProps()}
				>
					{customTrigger}
				</span>
			) : (
				<button
					ref={refs.setReference}
					aria-label={triggerAccessibleText}
					className={iconTriggerClasses}
					type='button'
					{...getReferenceProps()}
				>
					<Icon
						className={`${baseClass}__icon`}
						iconName={triggerIcon}
						size={triggerIconSize}
					/>
				</button>
			)}
			{isMounted && (
				<FloatingPortal>
					<div
						ref={refs.setFloating}
						aria-hidden={!isOpen}
						className={`${baseClass}__container`}
						style={{
							...floatingStyles,
							...transitionStyles,
							zIndex: zIndex,
							pointerEvents: isOpen ? 'auto' : 'none',
						}}
						{...getFloatingProps()}
					>
						{content}
					</div>
				</FloatingPortal>
			)}
		</div>
	);
};
