import React, { ComponentPropsWithoutRef } from 'react';

import { mergeClasses } from '@libs/components/utils';

import './platform-icon.css';

export type PlatformSize = 'xs' | 's' | 'm' | 'l' | 'xl' | '2xl' | '3xl';

export type PlatformType =
	| 'drupal'
	| 'gatsby'
	| 'google'
	| 'import-custom'
	| 'microsoft'
	| 'next'
	| 'splunk'
	| 'sumo-logic'
	| 'wordpress';

export interface PlatformIconProps extends ComponentPropsWithoutRef<'div'> {
	className?: string;
	platformType: PlatformType;
	/**
	 * Which size of icon to render
	 */
	size?: PlatformSize;
}

/**
 * PlatformIcon UI component
 */
export const PlatformIcon = ({
	className,
	platformType,
	size = '2xl',
	...props
}: PlatformIconProps) => {
	// Set up classes.
	const baseClass = 'pds-platform-icon';
	const platformClass = `pds-platform-icon--${platformType}`;
	const sizeClass = `pds-platform-icon--${size}`;

	// Render the output
	return (
		<div
			className={mergeClasses([baseClass, platformClass, sizeClass, className])}
			{...props}
		>
			{svgData[platformType]}
		</div>
	);
};

