import React, {
	createContext,
	ReactNode,
	useCallback,
	useContext,
	useState,
} from 'react';

interface OverlayContextType {
	closeOverlay: () => void;
	hasOpenOverlay: boolean;
	openOverlay: () => void;
}

export const OverlayContext = createContext<OverlayContextType | null>(null);

// Stable no-op default returned when no OverlayContextProvider is present.
// The provider is optional: overlay components render standalone without it.
// Without a provider `hasOpenOverlay` is always false, so `useKeyboardShortcut`
// simply won't auto-suppress shortcuts while overlays are open.
// Defined at module scope so its identity never changes and effects don't churn.
const NOOP_OVERLAY_CONTEXT: OverlayContextType = {
	closeOverlay: () => {},
	hasOpenOverlay: false,
	openOverlay: () => {},
};

export const OverlayContextProvider = ({
	children,
}: {
	children: ReactNode;
}) => {
	const [overlayCount, setOverlayCount] = useState(0);

	const openOverlay = useCallback(() => {
		setOverlayCount((prev) => prev + 1);
	}, []);

	const closeOverlay = useCallback(() => {
		setOverlayCount((prev) => Math.max(0, prev - 1));
	}, []);

	const hasOpenOverlay = overlayCount > 0;

	// Keyboard-shortcut suppression while an overlay is open is handled by
	// `useKeyboardShortcut`, which reads `hasOpenOverlay` and disables itself.
	// The provider only needs to track and expose that state.

	const contextValue: OverlayContextType = {
		closeOverlay,
		hasOpenOverlay,
		openOverlay,
	};

	return (
		<OverlayContext.Provider value={contextValue}>
			{children}
		</OverlayContext.Provider>
	);
};

export const useOverlayContext = () =>
	useContext(OverlayContext) ?? NOOP_OVERLAY_CONTEXT;
