import React from 'react';

import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

import { initiateSlots, mergeClasses } from '@libs/components/utils';

import { Icon } from '@components/icons/Icon/Icon';

import type { SortableListColumn, SortableRowProps } from './types';

import './sortable-list.css';

interface SortableRowInternalProps {
	columns?: SortableListColumn[];
	depth?: number;
	hasChildren?: boolean;
	isDragActive?: boolean;
	isDragging?: boolean;
	isDropTarget?: boolean;
	isExpanded?: boolean;
	isProjectedParent?: boolean;
	onToggleExpand?: () => void;
	projectedDepthDelta?: number;
}

export const SortableRow = ({
	children,
	className,
	columns,
	depth = 0,
	hasChildren = false,
	id,
	isDragActive = false,
	isDragging: _isDraggingProp = false,
	isDropTarget = false,
	isExpanded = false,
	isLocked = false,
	isProjectedParent = false,
	onToggleExpand,
	projectedDepthDelta,
	...props
}: SortableRowProps & SortableRowInternalProps) => {
	const {
		attributes,
		isDragging,
		listeners,
		setNodeRef,
		transform,
		transition,
	} = useSortable({
		attributes: { role: 'listitem', roleDescription: 'sortable' },
		disabled: isLocked,
		id,
	});

	// aria-pressed is only valid on role="button"; strip it since we use role="listitem"
	const { 'aria-pressed': _ariaPressed, ...safeAttributes } = attributes;

	const baseClass = 'pds-sortable-row';
	const lockedClass = isLocked ? `${baseClass}--locked` : null;
	const draggingClass = isDragging ? `${baseClass}--dragging` : null;
	const depthProjectingClass =
		isDragging && projectedDepthDelta !== undefined
			? `${baseClass}--depth-projecting`
			: null;
	const dropTargetClass = isDropTarget ? `${baseClass}--drop-target` : null;
	const projectedParentClass = isProjectedParent
		? `${baseClass}--projected-parent`
		: null;

	const style: React.CSSProperties = {
		...(isDragging && projectedDepthDelta !== undefined
			? ({
					'--projected-depth-delta': projectedDepthDelta,
				} as React.CSSProperties)
			: {}),
		transform: CSS.Transform.toString(transform),
		transition,
	};

	const slots = columns ? initiateSlots(children) : null;

	const contentStyle = columns
		? {
				display: 'grid',
				gridTemplateColumns: columns.map((c) => c.width).join(' '),
			}
		: undefined;

	// Apply drag listeners to the whole row when drag is active and row is not locked
	const dragProps =
		isDragActive && !isLocked
			? {
					...safeAttributes,
					...listeners,
				}
			: {};

	return (
		<div
			ref={setNodeRef}
			aria-level={depth + 1}
			className={mergeClasses([
				baseClass,
				lockedClass,
				draggingClass,
				depthProjectingClass,
				dropTargetClass,
				projectedParentClass,
				className ?? '',
			])}
			data-depth={depth}
			data-id={id}
			role='listitem'
			style={style}
			{...(hasChildren ? { 'aria-expanded': isExpanded } : {})}
			{...dragProps}
			{...props}
		>
			{hasChildren ? (
				<button
					aria-label={isExpanded ? 'Collapse' : 'Expand'}
					className={`${baseClass}__chevron`}
					onClick={onToggleExpand}
					tabIndex={isDragActive ? -1 : undefined}
					type='button'
				>
					<Icon
						className={mergeClasses([
							`${baseClass}__chevron-icon`,
							isExpanded ? `${baseClass}__chevron-icon--expanded` : '',
						])}
						iconName='angleDown'
						size='m'
					/>
				</button>
			) : (
				<div className={`${baseClass}__chevron-spacer`} />
			)}

			<div className={`${baseClass}__content`} style={contentStyle}>
				{columns && slots
					? columns.map((col) => (
							<div key={col.id} className={`${baseClass}__cell`}>
								<span className='visually-hidden'>{col.label}: </span>
								{slots[col.id] ?? null}
							</div>
						))
					: children}
			</div>
		</div>
	);
};
