import React, { ReactNode, useEffect, useState } from 'react';

import { mergeClasses } from '@libs/components/utils';
import { ValidationStatus } from '@libs/types/input-types';

import { useDropdown } from '@utilities/hooks/useDropdown';

import { DropdownSelectedIcon } from '@components/Dropdown/DropdownSelectedIcon';
import { Icon, PDSIcon } from '@components/icons/Icon/Icon';
import { PlatformIcon } from '@components/icons/PlatformIcon/PlatformIcon';

import {
	getInputWidthStyle,
	inputCommonClasses,
	InputLabel,
	InputMessage,
	InputPrefix,
	isOptionGroup,
	SelectOption,
} from '../input-utilities';

import './select.css';

// Select icon type - supports both PDS icons and platform icons
export type SelectIconType = PDSIcon | 'google' | 'microsoft';

// Select size type.
export type SelectSize = 's' | 'm';

// Label strings type.
type LabelStrings = {
	selectOptionText: string;
	triggerButton: string;
};

// Select option type.
export type SelectOptionType = {
	/**
	 * Option disabled.
	 */
	disabled?: boolean;
	/**
	 * Optional icon to display before the option label.
	 */
	icon?: SelectIconType;
	/**
	 * Option label.
	 */
	label: string;
	/**
	 * Option value.
	 */
	value: string;
};

// Select option group type.
export type SelectOptionGroupType = {
	/**
	 * Group label.
	 */
	groupLabel: string;
	/**
	 * Options within this group.
	 */
	options: SelectOptionType[];
};

export type SelectOptionsType = (SelectOptionType | SelectOptionGroupType)[];

interface SelectOptionGroupProps {
	children: ReactNode;
	label: string;
}

/**
 * Prop types for Select
 */
export interface SelectProps {
	/**
	 * Automatically resize the select to fit the longest option label. Defaults to false (width: 100%).
	 */
	autoWidth?: boolean;
	/**
	 * Additional class names
	 */
	className?: string;
	/**
	 * Optional default value for the field. Must match the value of one of the options. Cannot be used in conjunction with the `value` prop.
	 */
	defaultValue?: string;
	/**
	 * Is the field disabled?
	 */
	disabled?: boolean;
	/**
	 * Optional icon to display before the placeholder text (selectOptionText). Only shows when no value is selected.
	 */
	icon?: SelectIconType;
	/**
	 * Input ID.
	 */
	id: string;
	/**
	 * Width of the input field in pixels. When omitted, the input fills its container.
	 */
	inputWidth?: number;
	/**
	 * Field label.
	 */
	label: string;
	/**
	 * Translation strings for various labels or other visually-hidden text.
	 */
	labelStrings?: LabelStrings;
	/**
	 * Message or description used to help clarify the usage of the input.
	 */
	message?: string | ReactNode;
	/**
	 * onBlur event handler to provide the current value of the input.
	 */
	onBlur?: (currentValue: string) => void;
	/**
	 * onFocus event handler to provide the current value of the input.
	 */
	onFocus?: (currentValue: string) => void;
	/**
	 * Callback function when an option is selected.
	 */
	onOptionSelect?: (option: SelectOptionType) => void;
	/**
	 * Array of options for the select field.
	 */
	options?: SelectOptionsType;
	/**
	 * Is this field required?
	 */
	required?: boolean;
	/**
	 * Should the label be visible? If false, it will render for screen readers only.
	 */
	showLabel?: boolean;
	/**
	 * Should the selected option show a checkmark icon in the dropdown list? Defaults to true.
	 */
	showSelectedIcon?: boolean;
	/**
	 * Size of the select field.
	 */
	size?: SelectSize;
	/**
	 * Optional tooltip text to display additional information.
	 */
	tooltipText?: string | null;
	/**
	 * Validation message for the input field based on the validation status.
	 */
	validationMessage?: string;
	/**
	 * Validation status of the input field.
	 */
	validationStatus?: ValidationStatus;
	/**
	 * Value of the field. Must match the value of one of the options. Used to set the value of the field when controlled. Cannot be used in conjunction with the `defaultValue` prop.
	 */
	value?: string;
}

/**
 * SelectOptionGroup component
 */
export const SelectOptionGroup = ({
	children,
	label,
}: SelectOptionGroupProps) => {
	const baseClass = 'pds-select';

	return (
		<li className={`${baseClass}__group`} role='presentation'>
			<span className='pds-dropdown__heading'>{label}</span>
			<ul className={`${baseClass}__group-options`} role='group'>
				{children}
			</ul>
		</li>
	);
};

/**
 * Select UI component
 */
export const Select = ({
	autoWidth = false,
	className,
	defaultValue,
	disabled,
	icon,
	id,
	inputWidth,
	label,
	labelStrings = {
		selectOptionText: 'Select an option...',
		triggerButton: 'Toggle dropdown menu',
	},
	message,
	onBlur,
	onFocus,
	onOptionSelect,
	options,
	required = false,
	showLabel = true,
	showSelectedIcon = true,
	size = 's',
	tooltipText = null,
	validationMessage,
	validationStatus,
	value,
	...props
}: SelectProps) => {
	// Determine input width style.
	const inputWidthStyle = getInputWidthStyle(inputWidth);

	// Set up classes.
	const baseClass = 'pds-select';
	const autoWidthClass = autoWidth ? `${baseClass}--auto-width` : null;
	const sizeClass = size !== 's' ? `${baseClass}--${size}` : null;
	const disabledClass = disabled ? inputCommonClasses.disabled : null;
	const requiredClass =
		required && !disabled ? inputCommonClasses.required : null;
	const errorClass =
		validationStatus === 'error' ? inputCommonClasses.error : null;
	const successClass =
		validationStatus === 'success' ? inputCommonClasses.success : null;

	// Set decorators.
	let decorator = null;
	if (validationStatus === 'error') {
		decorator = 'error';
	}
	if (validationStatus === 'success') {
		decorator = 'success';
	}

	// If there is a validation message, use that. Otherwise, use the message prop.
	const processedMessage = validationMessage || message;

	// Determine if the input is controlled.
	const isControlled = typeof value != 'undefined';

	// When a component is not controlled, it can have a defaultValue.
	const hasDefaultValue = typeof defaultValue != 'undefined';

	const getFlatOptions = (options: SelectOptionsType): SelectOptionType[] => {
		return options.reduce((acc: SelectOptionType[], curr) => {
			if (isOptionGroup(curr)) {
				return [...acc, ...curr.options];
			}
			return [...acc, curr as SelectOptionType];
		}, []);
	};

	const flatOptions = getFlatOptions(options);

	// Function to get the index from the value.
	const getIndexFromValue = (value: string) =>
		flatOptions.findIndex((option) => option.value === value);

	// If the input is controlled, use the value prop to get the default index.
	const controlledValueIndex =
		isControlled && getIndexFromValue(value) >= 0
			? getIndexFromValue(value)
			: null;

	// If the input in uncontrolled, use the defaultValue prop to get the default index.
	const internalValueIndex = hasDefaultValue
		? getIndexFromValue(defaultValue)
		: null;

	// Determine if the input has a default value either from props or internal state.
	const startingValueIndex = controlledValueIndex || internalValueIndex;

	// Set up state.
	const [selectedIndex, setSelectedIndex] = useState(
		startingValueIndex ?? null,
	);

	// Shared dropdown hook.
	const {
		activeIndex,
		floatingStyles,
		getFloatingProps,
		getItemProps,
		getReferenceProps,
		isMounted,
		listRef,
		refs,
		setIsOpen,
		transitionStyles,
	} = useDropdown({
		enableClick: !disabled,
		enableTypeahead: true,
		role: 'listbox',
		selectedIndex,
		variant: 'input',
	});

	// Get label from selected item.
	const selectedItemLabel =
		selectedIndex !== null ? flatOptions[selectedIndex]?.label : undefined;

	// Get icon from selected item.
	const selectedItemIcon =
		selectedIndex !== null ? flatOptions[selectedIndex]?.icon : undefined;

	// Get value from selected item.
	const selectedItemValue =
		selectedIndex !== null ? flatOptions[selectedIndex]?.value : undefined;

	// Handle selection.
	const handleSelection = (index: number) => {
		const option = flatOptions[index];

		// If the option is controlled it will be handled externally via the useEffect below.
		// If the option is uncontrolled, update the selected index here.
		if (!isControlled) {
			setSelectedIndex(index);
			setIsOpen(false);
		}

		// If onOptionSelect callback.
		if (onOptionSelect) {
			onOptionSelect(option);
		}
	};

	// Update the selectedIndex when the value prop changes.
	useEffect(() => {
		if (isControlled) {
			const index = getIndexFromValue(value);
			setSelectedIndex(index);
			setIsOpen(false);
		}
	}, [value]);

	// Get the current value of the input field when the input loses focus.
	const handleBlur = () => {
		if (onBlur) {
			onBlur(selectedItemValue);
		}
	};

	// Get the current value of the input field when the input gains focus.
	const handleFocus = () => {
		if (onFocus) {
			onFocus(selectedItemValue);
		}
	};

	// Focus the input field.
	const focusInput = () => {
		(refs.reference.current as HTMLElement).focus();
	};

	// L gets 'l' icon; S/M use 'm' with CSS scale-down for S.

	// Helper function to render the appropriate icon component
	const renderIcon = (iconType: SelectIconType, className?: string) => {
		const isPlatformIcon = iconType === 'google' || iconType === 'microsoft';

		const resolvedIconSize = 'm';

		if (isPlatformIcon) {
			return (
				<PlatformIcon
					className={className}
					platformType={iconType as 'google' | 'microsoft'}
					size={resolvedIconSize}
				/>
			);
		}

		return (
			<Icon
				className={className}
				iconName={iconType as PDSIcon}
				size={resolvedIconSize}
			/>
		);
	};

	// Render options with group support
	const renderOptions = (options: SelectOptionsType) => {
		let currentIndex = 0;

		return options.map((option) => {
			if (isOptionGroup(option)) {
				const groupOptions = option.options.map((groupOption) => {
					const optionIndex = currentIndex++;
					return (
						<SelectOption
							key={optionIndex}
							ref={(node) => {
								listRef.current[optionIndex] = node;
							}}
							aria-disabled={groupOption?.disabled}
							aria-selected={
								optionIndex === selectedIndex && optionIndex === activeIndex
							}
							tabIndex={optionIndex === activeIndex ? 0 : -1}
							{...(!groupOption?.disabled &&
								getItemProps({
									onClick() {
										handleSelection(optionIndex);
									},
									onKeyDown(e) {
										if (e.key === 'Enter') {
											e.preventDefault();
											handleSelection(optionIndex);
											(refs.reference.current as HTMLElement).focus();
										}
										if (e.key === 'Escape') {
											e.preventDefault();
											(refs.reference.current as HTMLElement).focus();
										}
									},
								}))}
						>
							<span className={`${baseClass}__option-label`}>
								{groupOption.icon &&
									renderIcon(groupOption.icon, `${baseClass}__option-icon`)}
								{groupOption.label}
							</span>
							{showSelectedIcon && selectedIndex === optionIndex && (
								<DropdownSelectedIcon />
							)}
						</SelectOption>
					);
				});

				return (
					<SelectOptionGroup key={option.groupLabel} label={option.groupLabel}>
						{groupOptions}
					</SelectOptionGroup>
				);
			}

			const optionIndex = currentIndex++;
			return (
				<SelectOption
					key={optionIndex}
					ref={(node) => {
						listRef.current[optionIndex] = node;
					}}
					aria-disabled={option?.disabled}
					aria-selected={
						optionIndex === selectedIndex && optionIndex === activeIndex
					}
					tabIndex={optionIndex === activeIndex ? 0 : -1}
					{...(!option?.disabled &&
						getItemProps({
							onClick() {
								handleSelection(optionIndex);
							},
							onKeyDown(e) {
								if (e.key === 'Enter') {
									e.preventDefault();
									handleSelection(optionIndex);
									(refs.reference.current as HTMLElement).focus();
								}
								if (e.key === 'Escape') {
									e.preventDefault();
									(refs.reference.current as HTMLElement).focus();
								}
							},
						}))}
				>
					<span className={`${baseClass}__option-label`}>
						{option.icon &&
							renderIcon(option.icon, `${baseClass}__option-icon`)}
						{option.label}
					</span>
					{showSelectedIcon && selectedIndex === optionIndex && (
						<DropdownSelectedIcon />
					)}
				</SelectOption>
			);
		});
	};

	// Render the output
	return (
		<div
			className={mergeClasses([
				inputCommonClasses.base,
				baseClass,
				autoWidthClass,
				sizeClass,
				disabledClass,
				requiredClass,
				errorClass,
				successClass,
				className ?? '',
			])}
			style={inputWidth ? inputWidthStyle : null}
			{...props}
		>
			{autoWidth && !inputWidth && (
				<div aria-hidden='true' className={`${baseClass}__sizer`}>
					{flatOptions.map((option) => (
						<span key={option.value} className={`${baseClass}__input-wrapper`}>
							{validationStatus !== undefined && (
								<InputPrefix variant='error' />
							)}
							<span className={`${baseClass}__input-inner`}>
								<span className={`${baseClass}__option-text`}>
									{option.icon && renderIcon(option.icon, `${baseClass}__icon`)}
									{option.label}
								</span>
								<Icon
									className={`${baseClass}__trigger-icon`}
									iconName='angleDown'
								/>
							</span>
						</span>
					))}
				</div>
			)}

			<InputLabel
				disabled={disabled}
				id={id}
				label={label}
				required={required}
				showLabel={showLabel}
				tooltipText={tooltipText}
			/>

			<span
				ref={refs.setReference}
				aria-autocomplete='none'
				aria-labelledby={`${id}-label`}
				className={`${baseClass}__input-wrapper`}
				id={id}
				tabIndex={0}
				{...getReferenceProps({
					onClick: focusInput,
					onBlur: handleBlur,
					onFocus: handleFocus,
				})}
			>
				{decorator && <InputPrefix variant={decorator} />}
				<span className={`${baseClass}__input-inner`}>
					<span className={`${baseClass}__option-text`}>
						{(selectedItemIcon || (!selectedItemLabel && icon)) &&
							renderIcon(selectedItemIcon || icon, `${baseClass}__icon`)}
						<span className={`${baseClass}__option-label-text`}>
							{selectedItemLabel ?? labelStrings.selectOptionText}
						</span>
					</span>
					<Icon className={`${baseClass}__trigger-icon`} iconName='angleDown' />
				</span>
			</span>

			{isMounted && (
				<div
					ref={refs.setFloating}
					className={`pds-dropdown__panel ${baseClass}__dropdown`}
					style={{
						...floatingStyles,
						zIndex: 'var(--pds-z-index-dropdown)',
					}}
					{...getFloatingProps()}
				>
					<div style={{ ...transitionStyles }}>
						<ul className={`${baseClass}__options`} role='group'>
							{renderOptions(options)}
						</ul>
					</div>
				</div>
			)}

			{processedMessage && (
				<InputMessage
					hasValidationMessage={validationMessage ? true : false}
					id={id}
					message={processedMessage}
					validationMessageHasDecorators={false}
					validationStatus={validationStatus}
				/>
			)}
		</div>
	);
};
