import React, {
	Children,
	forwardRef,
	isValidElement,
	ReactElement,
	useCallback,
	useImperativeHandle,
	useMemo,
	useRef,
	useState,
} from 'react';

import {
	Announcements,
	closestCenter,
	CollisionDetection,
	DndContext,
	DragEndEvent,
	DragOverEvent,
	DragOverlay,
	DragStartEvent,
	KeyboardCoordinateGetter,
	KeyboardSensor,
	MeasuringStrategy,
	PointerSensor,
	UniqueIdentifier,
	useSensor,
	useSensors,
} from '@dnd-kit/core';
import {
	SortableContext,
	sortableKeyboardCoordinates,
	SortingStrategy,
	verticalListSortingStrategy,
} from '@dnd-kit/sortable';

import { mergeClasses } from '@libs/components/utils';

import { findItem, getProjectedDepth } from './sortable-utils';
import { SortableListHeader } from './SortableListHeader';
import type {
	FlattenedNode,
	SortableListProps,
	SortableRowMeta,
} from './types';
import { useSortableTree } from './useSortableTree';

import './sortable-list.css';

const INDENT_SIZE = 24;

const measuring = {
	droppable: {
		strategy: MeasuringStrategy.Always,
	},
};

export interface SortableListHandle {
	/** Reverts the list to the order it was in when drag mode was last enabled. */
	resetToSnapshot: () => void;
}

export const SortableList = forwardRef<SortableListHandle, SortableListProps>(
	function SortableList(
		{
			children,
			className,
			columns,
			defaultItems,
			getItemLabel = (item) => String(item.id),
			isDragEnabled: isDragEnabledProp,
			isItemLocked = () => false,
			isNestingLocked = () => false,
			items,
			maxDepth = 0,
			onReorder,
			renderRow,
			reorderMode = 'always',
			screenReaderInstructions,
			...props
		},
		ref,
	) {
		const baseClass = 'pds-sortable-list';

		const [activeId, setActiveId] = useState<UniqueIdentifier | null>(null);
		const activeIdRef = useRef<UniqueIdentifier | null>(null);
		const [isKeyboardDrag, setIsKeyboardDrag] = useState(false);
		const isKeyboardDragRef = useRef(false);
		const [overId, setOverId] = useState<UniqueIdentifier | null>(null);
		const dragStartXRef = useRef(0);
		// Raw x delta — kept as a ref so announcement callbacks always see the
		// latest value without needing it in their dep array.
		const dragOffsetXRef = useRef(0);
		const lastInteractionRef = useRef<'keyboard' | 'pointer'>('pointer');
		const activeNodeDepthRef = useRef(0);
		// When an expanded node is dragged, it's auto-collapsed so only the parent
		// moves with the overlay. This ref tracks it so expansion is restored after.
		const autoCollapsedIdRef = useRef<string | null>(null);

		// Tracks how many times Left/Right was pressed during a keyboard drag.
		// The ref is read in handleDragEnd (avoids closure staleness).
		// The state drives the drag overlay's visual indentation.
		const [keyboardDepthDelta, setKeyboardDepthDelta] = useState(0);
		const keyboardDepthDeltaRef = useRef(0);

		// Committed depth delta for mouse drags — has hysteresis so small cursor
		// oscillations don't flip the depth. Once depth increases (e.g. 0→1 at 12px
		// rightward), it stays until the cursor moves back past the sticky threshold.
		// State drives the visual; ref is read in handleDragEnd.
		const [committedDepthDelta, setCommittedDepthDelta] = useState(0);
		const committedDepthDeltaRef = useRef(0);

		// Custom coordinate getter: intercepts Left/Right during keyboard drag to
		// adjust nesting depth. Shifts x so the DragOverlay physically moves
		// left/right, giving clear visual feedback of the depth change.
		const coordinateGetter = useCallback<KeyboardCoordinateGetter>(
			(event, args) => {
				if (
					maxDepth > 0 &&
					(event.key === 'ArrowLeft' || event.key === 'ArrowRight')
				) {
					event.preventDefault();
					const delta = event.key === 'ArrowRight' ? 1 : -1;
					const prev = keyboardDepthDeltaRef.current;
					const next = Math.max(-maxDepth, Math.min(maxDepth, prev + delta));
					const actual = next - prev;
					keyboardDepthDeltaRef.current = next;
					setKeyboardDepthDelta(next);
					return {
						x: args.currentCoordinates.x + actual * INDENT_SIZE,
						y: args.currentCoordinates.y,
					};
				}
				return sortableKeyboardCoordinates(event, args);
			},
			[maxDepth],
		);

		const isDragActive =
			reorderMode === 'always' ||
			(reorderMode === 'toggle' && (isDragEnabledProp ?? false));

		const {
			currentItems,
			expandItem,
			flatNodes,
			handleReorder,
			resetToSnapshot,
			sortableIds,
			toggleExpand,
		} = useSortableTree({
			defaultItems,
			isDragEnabled: isDragActive,
			items,
			onReorder,
		});

		useImperativeHandle(ref, () => ({ resetToSnapshot }), [resetToSnapshot]);

		const sensors = useSensors(
			useSensor(PointerSensor, {
				activationConstraint: {
					distance: 5,
				},
			}),
			useSensor(KeyboardSensor, {
				coordinateGetter,
			}),
		);

		const reorderActiveClass = isDragActive
			? `${baseClass}--reorder-active`
			: null;

		const lockedIds = useMemo(
			() =>
				new Set(flatNodes.filter((n) => isItemLocked(n.data)).map((n) => n.id)),
			[flatNodes, isItemLocked],
		);

		const nestingLockedIds = useMemo(
			() =>
				new Set(
					flatNodes.filter((n) => isNestingLocked(n.data)).map((n) => n.id),
				),
			[flatNodes, isNestingLocked],
		);

		// A valid nest target is a node that can receive a dropped item as its first
		// child — either a closed parent (has children but is collapsed) or a leaf
		// node at a depth that can still accept children. In both cases the node stays
		// in place during drag and shows the drop-target border instead of jumping.
		const isNestTarget = useCallback(
			(id: UniqueIdentifier) => {
				if (maxDepth === 0) return false;
				if (nestingLockedIds.has(String(id))) return false;
				const node = flatNodes.find((n) => n.id === id);
				if (!node) return false;
				if (node.depth >= maxDepth) return false;
				// Closed parent: has children but is collapsed.
				if (node.hasChildren) return !node.isExpanded;
				// Leaf node: can accept a first child.
				return true;
			},
			[flatNodes, maxDepth, nestingLockedIds],
		);

		// When hovering over a valid nest target, suppress item displacement entirely.
		// The target stays put and receives the --drop-target highlight; dropping
		// nests the dragged item inside it as its first child.
		const sortingStrategy = useCallback<SortingStrategy>(
			(args) => {
				if (overId && isNestTarget(overId)) {
					return null;
				}
				return verticalListSortingStrategy(args);
			},
			[isNestTarget, overId],
		);

		// Locked rows that sit between the dragged item and its current hover target.
		// These are blocking the drop — used for visual feedback.
		const blockingDropIds = useMemo(() => {
			if (!activeId || !overId || lockedIds.size === 0 || activeId === overId) {
				return new Set<string>();
			}
			// Dropping onto a nest target nests inside it — no items are displaced,
			// so nothing can be blocking.
			if (isNestTarget(overId)) {
				return new Set<string>();
			}
			const activeIndex = flatNodes.findIndex((n) => n.id === activeId);
			const overIndex = flatNodes.findIndex((n) => n.id === overId);
			if (activeIndex === -1 || overIndex === -1) return new Set<string>();
			// Exclude the over item itself — hovering over a locked item to nest
			// inside it doesn't displace it. Only items strictly between active
			// and over can be displaced.
			const [min, max] =
				activeIndex < overIndex
					? [activeIndex + 1, overIndex - 1]
					: [overIndex + 1, activeIndex - 1];
			return new Set(
				flatNodes
					.slice(min, max + 1)
					.filter((n) => lockedIds.has(n.id))
					.map((n) => n.id),
			);
		}, [activeId, flatNodes, isNestTarget, lockedIds, overId]);

		const isInvalidDrop = blockingDropIds.size > 0;

		const activeNode = useMemo(() => {
			if (!activeId) return null;
			return flatNodes.find((n) => n.id === activeId) ?? null;
		}, [activeId, flatNodes]);

		const activeItem = useMemo(() => {
			if (!activeId) return null;
			return findItem(currentItems, String(activeId)) ?? null;
		}, [activeId, currentItems]);

		const projectedDragDepth = useMemo(() => {
			const baseDepth = activeNode?.depth ?? 0;
			if (!activeId || !overId || isKeyboardDrag || maxDepth === 0)
				return baseDepth;
			return getProjectedDepth(
				flatNodes,
				String(activeId),
				String(overId),
				committedDepthDelta * INDENT_SIZE,
				INDENT_SIZE,
				maxDepth,
			);
		}, [
			activeId,
			activeNode,
			committedDepthDelta,
			flatNodes,
			isKeyboardDrag,
			maxDepth,
			overId,
		]);

		// When nesting is projected during a mouse drag, highlight the item that
		// will become the parent — so users know exactly which item owns the drop.
		const projectedParentId = useMemo(() => {
			if (!activeId || isKeyboardDrag || projectedDragDepth === 0) return null;
			// Nest target gets --drop-target, not --projected-parent.
			if (overId && isNestTarget(overId)) return null;
			const activeIndex = flatNodes.findIndex((n) => n.id === activeId);
			if (activeIndex === -1) return null;
			return findParentAtDepth(flatNodes, activeIndex, projectedDragDepth);
		}, [
			activeId,
			flatNodes,
			isNestTarget,
			isKeyboardDrag,
			overId,
			projectedDragDepth,
		]);

		const handleDragStart = useCallback(
			(event: DragStartEvent) => {
				const { active } = event;
				const isKb = lastInteractionRef.current === 'keyboard';
				const node = flatNodes.find((n) => n.id === active.id);
				setActiveId(active.id);
				activeIdRef.current = active.id;
				setIsKeyboardDrag(isKb);
				isKeyboardDragRef.current = isKb;
				activeNodeDepthRef.current = node?.depth ?? 0;
				setOverId(null);
				dragStartXRef.current = 0;
				dragOffsetXRef.current = 0;
				committedDepthDeltaRef.current = 0;
				setCommittedDepthDelta(0);
				keyboardDepthDeltaRef.current = 0;
				setKeyboardDepthDelta(0);

				// Auto-collapse expanded nodes so children don't float in place
				// while only the parent row moves with the drag overlay.
				if (node?.hasChildren && node?.isExpanded) {
					toggleExpand(String(active.id));
					autoCollapsedIdRef.current = String(active.id);
				}
			},
			[flatNodes, toggleExpand],
		);

		// Custom collision detection that prevents dnd-kit from visually reordering
		// items into positions that would displace a locked row. When the closest
		// collision is blocked, falls through to the next closest valid one so the
		// placeholder can still reach positions adjacent to the locked row.
		const collisionDetection: CollisionDetection = useCallback(
			(args) => {
				const collisions = closestCenter(args);
				if (
					!collisions.length ||
					!activeIdRef.current ||
					lockedIds.size === 0
				) {
					return collisions;
				}
				const activeIndex = flatNodes.findIndex(
					(n) => n.id === activeIdRef.current,
				);
				for (const collision of collisions) {
					const collisionId = collision.id;
					if (collisionId === activeIdRef.current) return [collision];
					const overIndex = flatNodes.findIndex((n) => n.id === collisionId);
					if (activeIndex === -1 || overIndex === -1) return [collision];
					// Block collision with a locked item unless there is genuine nesting
					// intent. Upward drags always displace the item so they are always
					// skipped. For downward drags, allow the collision only when:
					//   (a) the item is a closed parent (drop-onto-closed-parent nesting),
					//   OR
					//   (b) nesting is allowed (not nesting-locked) AND the user has
					//       committed a rightward offset (depth delta > 0) — i.e. the
					//       drag is clearly aimed at nesting, not a position change.
					if (lockedIds.has(String(collisionId))) {
						if (activeIndex > overIndex) continue;
						const nestingAllowed = !nestingLockedIds.has(String(collisionId));
						const hasNestingIntent =
							maxDepth > 0 && committedDepthDeltaRef.current > 0;
						if (
							!isNestTarget(collisionId) &&
							(!nestingAllowed || !hasNestingIntent)
						)
							continue;
					}
					// Check items strictly between active and over. The over item
					// itself is excluded because hovering over a locked item is valid
					// for nesting; hasDisplacedLock in handleDragEnd catches any
					// actual position change on drop.
					const [min, max] =
						activeIndex < overIndex
							? [activeIndex + 1, overIndex - 1]
							: [overIndex + 1, activeIndex - 1];
					const wouldDisplace = flatNodes
						.slice(min, max + 1)
						.some((n) => lockedIds.has(n.id));
					if (!wouldDisplace) return [collision];
				}
				return [];
			},
			[flatNodes, lockedIds, nestingLockedIds],
		);

		const handleDragOver = useCallback(
			(event: DragOverEvent) => {
				const newOverId = event.over?.id ?? null;
				const currentActiveId = activeIdRef.current;

				if (
					newOverId &&
					currentActiveId &&
					newOverId !== currentActiveId &&
					lockedIds.size > 0
				) {
					const activeIndex = flatNodes.findIndex(
						(n) => n.id === currentActiveId,
					);
					const overIndex = flatNodes.findIndex((n) => n.id === newOverId);
					if (activeIndex !== -1 && overIndex !== -1) {
						const [min, max] =
							activeIndex < overIndex
								? [activeIndex + 1, overIndex]
								: [overIndex, activeIndex - 1];
						const wouldDisplaceLock = flatNodes
							.slice(min, max + 1)
							.some((n) => lockedIds.has(n.id));
						if (wouldDisplaceLock) return;
					}
				}

				setOverId(newOverId);
			},
			[flatNodes, lockedIds],
		);

		const handleDragMove = useCallback(
			(event: { delta: { x: number } }) => {
				const rawDelta = event.delta.x;
				dragOffsetXRef.current = rawDelta;

				if (isKeyboardDragRef.current || maxDepth === 0) return;

				// Math.floor means a full INDENT_SIZE of movement (not half) is
				// required to commit a depth change — less accidental than Math.round.
				const rawDepthDelta = Math.floor(rawDelta / INDENT_SIZE);
				const current = committedDepthDeltaRef.current;

				if (rawDepthDelta > current) {
					// Increase: commit immediately when the full threshold is crossed.
					committedDepthDeltaRef.current = rawDepthDelta;
					setCommittedDepthDelta(rawDepthDelta);
				} else if (rawDepthDelta < current) {
					// Decrease: require moving back 40% of INDENT_SIZE from the entry
					// threshold. This prevents the depth from flickering when the cursor
					// naturally oscillates near the boundary.
					const stayThreshold = current * INDENT_SIZE - INDENT_SIZE * 0.4;
					if (rawDelta < stayThreshold) {
						committedDepthDeltaRef.current = rawDepthDelta;
						setCommittedDepthDelta(rawDepthDelta);
					}
				}
			},
			[maxDepth],
		);

		const handleDragEnd = useCallback(
			(event: DragEndEvent) => {
				const { active, over } = event;

				// Capture before resetting — used below for depth calculation.
				const wasKeyboardDrag = isKeyboardDragRef.current;
				const capturedDepthDelta = keyboardDepthDeltaRef.current;
				const capturedMouseDepthDelta = committedDepthDeltaRef.current;

				setActiveId(null);
				activeIdRef.current = null;
				setIsKeyboardDrag(false);
				isKeyboardDragRef.current = false;
				setOverId(null);
				committedDepthDeltaRef.current = 0;
				setCommittedDepthDelta(0);

				if (autoCollapsedIdRef.current) {
					expandItem(autoCollapsedIdRef.current);
					autoCollapsedIdRef.current = null;
				}

				const activeIndex = flatNodes.findIndex((n) => n.id === active.id);
				const depthOffset = wasKeyboardDrag
					? capturedDepthDelta * INDENT_SIZE
					: capturedMouseDepthDelta * INDENT_SIZE;
				const isSamePosition = !over || active.id === over.id;

				// When keyboard Right without vertical movement: nest under item above.
				let effectiveOverId = over?.id ?? null;
				if (
					wasKeyboardDrag &&
					capturedDepthDelta > 0 &&
					isSamePosition &&
					activeIndex > 0
				) {
					effectiveOverId = flatNodes[activeIndex - 1].id;
				}

				// In-place depth change: same position, different depth.
				// Handles keyboard Left (un-nesting) and horizontal-only mouse drags.
				if (!effectiveOverId || active.id === effectiveOverId) {
					if (activeIndex === -1) return;
					const activeNodeData = flatNodes[activeIndex];
					if (!activeNodeData) return;
					// Use getProjectedDepth so the drop respects the same neighbor
					// constraints (maxAllowedByPrev, minAllowedByNext) as the visual.
					// Without this, a raw delta can compute a depth that has no valid
					// parent, causing the node to fall to root after buildTree.
					const newDepth = getProjectedDepth(
						flatNodes,
						String(active.id),
						String(active.id),
						depthOffset,
						INDENT_SIZE,
						maxDepth,
					);
					if (newDepth === activeNodeData.depth) return;
					const updatedNodes = [...flatNodes];
					const [movedNode] = updatedNodes.splice(activeIndex, 1);
					const newParentId = findParentAtDepth(
						updatedNodes,
						activeIndex,
						newDepth,
					);
					if (newParentId && nestingLockedIds.has(newParentId)) return;
					const updatedNode = {
						...movedNode,
						depth: newDepth,
						parentId: newParentId,
					};
					updatedNodes.splice(activeIndex, 0, updatedNode);
					const stableOriginal = flatNodes
						.filter((n) => n.id !== active.id)
						.map((n) => n.id);
					const stableUpdated = updatedNodes
						.filter((n) => n.id !== active.id)
						.map((n) => n.id);
					const hasDisplacedLock = stableOriginal.some((id, relativeIndex) => {
						if (!lockedIds.has(id)) return false;
						return stableUpdated.indexOf(id) !== relativeIndex;
					});
					if (hasDisplacedLock) return;
					handleReorder(updatedNodes);
					if (newDepth > 0 && newParentId) expandItem(newParentId);
					return;
				}

				const overIndex = flatNodes.findIndex((n) => n.id === effectiveOverId);

				if (activeIndex === -1 || overIndex === -1) return;

				const updatedNodes = [...flatNodes];
				const activeNodeDepth = updatedNodes[activeIndex].depth;
				const [movedNode] = updatedNodes.splice(activeIndex, 1);

				// Also splice out visible children (expanded subtree) so they
				// stay contiguous with the parent when re-inserted. Without this,
				// children end up before the parent in the flat list and buildTree
				// silently drops them because the parent isn't in nodeMap yet.
				const visibleChildren: FlattenedNode[] = [];
				while (
					updatedNodes.length > activeIndex &&
					updatedNodes[activeIndex].depth > activeNodeDepth
				) {
					visibleChildren.push(updatedNodes.splice(activeIndex, 1)[0]);
				}

				// overIndex in updatedNodes after active item is removed.
				// Using updatedNodes prevents the active item from being
				// incorrectly chosen as its own parent in findParentAtDepth.
				const updatedOverIndex = updatedNodes.findIndex(
					(n) => n.id === effectiveOverId,
				);

				let targetDepth: number;
				let targetParentId: string | null;

				if (isNestTarget(effectiveOverId)) {
					// Drop onto a nest target: become its first child
					const overNode = flatNodes[overIndex];
					targetDepth = Math.min(overNode.depth + 1, maxDepth);
					targetParentId = String(effectiveOverId);
				} else {
					targetDepth = getProjectedDepth(
						updatedNodes,
						String(active.id),
						String(effectiveOverId),
						depthOffset,
						INDENT_SIZE,
						maxDepth,
						movedNode.depth,
					);

					const overNodeInUpdated = updatedNodes[updatedOverIndex];
					if (
						overNodeInUpdated &&
						overNodeInUpdated.depth === targetDepth - 1
					) {
						// The over item itself is the intended parent — insert after
						// it so the dropped item appears as its child in the flat list.
						targetParentId = String(effectiveOverId);
					} else {
						targetParentId = findParentAtDepth(
							updatedNodes,
							updatedOverIndex,
							targetDepth,
						);
					}
				}

				// Abort if the drop would nest the item inside a nesting-locked row.
				if (targetParentId && nestingLockedIds.has(targetParentId)) return;

				const updatedNode: FlattenedNode = {
					...movedNode,
					depth: targetDepth,
					parentId: targetParentId,
				};

				// Nesting directly under the over item: insert right after it so
				// the dropped item appears as its first child in the flat list.
				// Otherwise: dragging down (active was before over) puts the item
				// after the over item; dragging up puts it at the over item's slot.
				const overNodeInUpdated = updatedNodes[updatedOverIndex];
				const nestingUnderOver =
					overNodeInUpdated &&
					overNodeInUpdated.depth === targetDepth - 1 &&
					targetParentId === String(effectiveOverId);
				const insertIndex =
					nestingUnderOver || activeIndex < overIndex
						? updatedOverIndex + 1
						: updatedOverIndex;
				updatedNodes.splice(insertIndex, 0, updatedNode, ...visibleChildren);

				// Abort if the proposed order would displace any locked item.
				// Compare each locked item's absolute index — locked items must not
				// move regardless of where the active subtree is reinserted.
				// Two exemptions:
				// - Items in the active subtree move legitimately with their parent.
				// - The nesting target: when active nests inside a locked item, that
				//   item shifts in the flat list (active moved from above it to inside
				//   it), which is not a true displacement.
				const activeSubtreeIds = new Set([
					String(active.id),
					...visibleChildren.map((c) => c.id),
				]);
				const hasDisplacedLock = flatNodes.some((node, originalIndex) => {
					if (!lockedIds.has(node.id)) return false;
					if (activeSubtreeIds.has(node.id)) return false;
					if (node.id === targetParentId) return false;
					const newIndex = updatedNodes.findIndex((n) => n.id === node.id);
					return newIndex !== originalIndex;
				});
				if (hasDisplacedLock) return;

				handleReorder(updatedNodes);

				// Expand the parent so the nested item is immediately visible.
				if (targetDepth > 0 && targetParentId !== null) {
					expandItem(targetParentId);
				}
			},
			[
				expandItem,
				flatNodes,
				handleReorder,
				isNestTarget,
				lockedIds,
				maxDepth,
				nestingLockedIds,
			],
		);

		const handleDragCancel = useCallback(() => {
			setActiveId(null);
			activeIdRef.current = null;
			setIsKeyboardDrag(false);
			isKeyboardDragRef.current = false;
			setOverId(null);
			dragOffsetXRef.current = 0;
			committedDepthDeltaRef.current = 0;
			setCommittedDepthDelta(0);
			keyboardDepthDeltaRef.current = 0;
			setKeyboardDepthDelta(0);

			if (autoCollapsedIdRef.current) {
				expandItem(autoCollapsedIdRef.current);
				autoCollapsedIdRef.current = null;
			}
		}, [expandItem]);

		const announcements = useMemo<Announcements>(
			() => ({
				onDragStart({ active }) {
					const node = flatNodes.find((n) => n.id === active.id);
					const item = findItem(currentItems, String(active.id));
					const label = item ? getItemLabel(item) : String(active.id);
					const position = node ? flatNodes.indexOf(node) + 1 : '?';
					return `Picked up ${label}. Current position: ${position} of ${flatNodes.length} at depth ${node?.depth ?? 0}.`;
				},
				onDragOver({ active, over }) {
					if (!over) return;
					const overIndex = flatNodes.findIndex((n) => n.id === over.id);
					if (overIndex === -1) return;
					const item = findItem(currentItems, String(active.id));
					const label = item ? getItemLabel(item) : String(active.id);
					const depth = getProjectedDepth(
						flatNodes,
						String(active.id),
						String(over.id),
						dragOffsetXRef.current,
						INDENT_SIZE,
						maxDepth,
					);
					return `Moving ${label}. Target position: ${overIndex + 1} of ${flatNodes.length} at depth ${depth}.`;
				},
				onDragEnd({ active, over }) {
					const item = findItem(currentItems, String(active.id));
					const label = item ? getItemLabel(item) : String(active.id);
					if (!over || active.id === over.id) {
						return `${label} dropped. No change in position.`;
					}
					const overIndex = flatNodes.findIndex((n) => n.id === over.id);
					const depth = getProjectedDepth(
						flatNodes,
						String(active.id),
						String(over.id),
						dragOffsetXRef.current,
						INDENT_SIZE,
						maxDepth,
					);
					return `${label} dropped at position ${overIndex + 1} of ${flatNodes.length} at depth ${depth}.`;
				},
				onDragCancel({ active }) {
					const node = flatNodes.find((n) => n.id === active.id);
					const item = findItem(currentItems, String(active.id));
					const label = item ? getItemLabel(item) : String(active.id);
					const position = node ? flatNodes.indexOf(node) + 1 : '?';
					return `Sorting cancelled. ${label} returned to position ${position} of ${flatNodes.length}.`;
				},
			}),
			[currentItems, flatNodes, getItemLabel, maxDepth],
		);

		const headerInternalProps = {
			columns,
		};

		const renderedChildren = Children.map(children, (child) => {
			if (isValidElement(child) && child.type === SortableListHeader) {
				return React.cloneElement(child as ReactElement, headerInternalProps);
			}
			return child;
		});

		return (
			<DndContext
				accessibility={{
					announcements,
					...(screenReaderInstructions
						? {
								screenReaderInstructions: {
									draggable: screenReaderInstructions,
								},
							}
						: {}),
				}}
				collisionDetection={collisionDetection}
				measuring={measuring}
				onDragCancel={handleDragCancel}
				onDragEnd={handleDragEnd}
				onDragMove={handleDragMove}
				onDragOver={handleDragOver}
				onDragStart={handleDragStart}
				sensors={sensors}
			>
				<SortableContext items={sortableIds} strategy={sortingStrategy}>
					<div
						className={mergeClasses([
							baseClass,
							reorderActiveClass,
							className ?? '',
						])}
						onKeyDownCapture={() => {
							lastInteractionRef.current = 'keyboard';
						}}
						onPointerDown={() => {
							lastInteractionRef.current = 'pointer';
						}}
						role='list'
						{...props}
					>
						{renderedChildren}

						{flatNodes.map((node) => {
							const meta: SortableRowMeta = {
								depth: node.depth,
								hasChildren: node.hasChildren,
								index: node.index,
								isDragging: node.id === activeId,
								isExpanded: node.isExpanded,
								isLocked: lockedIds.has(node.id),
								toggleExpand: () => toggleExpand(node.id),
							};

							const rendered = renderRow(node.data, meta);

							const isDraggingThisNode = node.id === activeId;
							const internalProps = {
								columns,
								depth: node.depth,
								hasChildren: node.hasChildren,
								isDragActive,
								isDragging: isDraggingThisNode,
								isDropTarget: node.id === overId && isNestTarget(node.id),
								isProjectedParent:
									node.id === projectedParentId &&
									!nestingLockedIds.has(node.id),
								isExpanded: node.isExpanded,
								...(lockedIds.has(node.id) ? { isLocked: true } : {}),
								onToggleExpand: () => toggleExpand(node.id),
								...(isDraggingThisNode && !isKeyboardDrag && maxDepth > 0
									? {
											projectedDepthDelta: projectedDragDepth - node.depth,
										}
									: {}),
							};

							if (isValidElement(rendered)) {
								return React.cloneElement(rendered as ReactElement, {
									key: node.id,
									...internalProps,
								});
							}

							return <div key={node.id}>{rendered}</div>;
						})}
					</div>
				</SortableContext>

				<DragOverlay>
					{activeId && activeItem ? (
						<div
							className={mergeClasses([
								'pds-sortable-list pds-sortable-list--overlay',
								isInvalidDrop ? 'pds-sortable-list--overlay-invalid' : null,
								isKeyboardDrag ? 'pds-sortable-list--overlay-keyboard' : null,
							])}
						>
							{(() => {
								const baseDepth = activeNode?.depth ?? 0;
								const overlayDepth = isKeyboardDrag
									? Math.max(
											0,
											Math.min(maxDepth, baseDepth + keyboardDepthDelta),
										)
									: baseDepth;
								const overlayMeta: SortableRowMeta = {
									depth: overlayDepth,
									hasChildren: activeNode?.hasChildren ?? false,
									index: activeNode?.index ?? 0,
									isDragging: true,
									isExpanded: false,
									isLocked: false,
									toggleExpand: () => {},
								};
								const rendered = renderRow(activeItem, overlayMeta);
								const overlayProps = {
									columns,
									depth: overlayDepth,
									hasChildren: overlayMeta.hasChildren,
									isDragActive: false,
									isDragging: false,
									isExpanded: false,
									onToggleExpand: () => {},
								};
								if (isValidElement(rendered)) {
									return React.cloneElement(
										rendered as ReactElement,
										overlayProps,
									);
								}
								return rendered;
							})()}
						</div>
					) : null}
				</DragOverlay>
			</DndContext>
		);
	},
);

function findParentAtDepth(
	flatNodes: FlattenedNode[],
	overIndex: number,
	targetDepth: number,
): string | null {
	if (targetDepth === 0) return null;

	for (let i = overIndex - 1; i >= 0; i--) {
		if (flatNodes[i].depth === targetDepth - 1) {
			return flatNodes[i].id;
		}
	}

	return null;
}
