import React, { MouseEvent, useState } from 'react';

import { mergeClasses } from '@libs/components/utils';

import { Tally } from '@components/badges/Tally/Tally';
import { Icon, PDSIcon } from '@components/icons/Icon/Icon';
import { Spinner } from '@components/loading-indicators/Spinner/Spinner';
import { Tooltip } from '@components/Tooltip/Tooltip';

import './segmented-button.css';

export type SegmentedButtonSize = 's' | 'm' | 'l';

/**
 * Structure for each option in the SegmentedButton component.
 */
interface OptionType {
	/**
	 * Disables this individual option.
	 */
	disabled?: boolean;
	/**
	 * Optional icon rendered before the label.
	 */
	iconName?: PDSIcon;
	/**
	 * Optional unique ID for the option. Falls back to a generated ID.
	 */
	id?: string;
	/**
	 * Shows a spinner before the label to indicate the option is loading.
	 */
	isLoading?: boolean;
	/**
	 * Visible text for the option.
	 */
	label: string;
	/**
	 * Optional tally badge rendered after the label.
	 */
	tally?: {
		label: string | number;
		type: 'neutral' | 'critical' | 'warning' | 'info' | 'success';
	};
	/**
	 * Value submitted when this option is selected.
	 */
	value: string;
}

/**
 * Interface for handling selection events.
 */
interface HandleSelectionEvent extends MouseEvent<HTMLInputElement> {
	target: HTMLInputElement;
}

/**
 * Prop types for SegmentedButton
 */
export interface SegmentedButtonProps {
	/**
	 * Renders a border around the track. Off by default.
	 */
	border?: boolean;
	/**
	 * Additional class names.
	 */
	className?: string;
	/**
	 * Optional initial selected option value.
	 */
	defaultValue?: string;
	/**
	 * Disables all options in the SegmentedButton.
	 */
	disabled?: boolean;
	/**
	 * Renders each option as an icon-only, square segment with a circular
	 * selected pill. Each option's `iconName` is required and its `label` is
	 * used as the accessible name (visually hidden) and shown in a tooltip on
	 * hover. Works at any size; the icon and pill scale with the size.
	 */
	iconOnly?: boolean;
	/**
	 * Unique ID for the SegmentedButton.
	 */
	id: string;
	/**
	 * Label for the SegmentedButton — visually hidden, used for screen readers only.
	 */
	label: string;
	/**
	 * Callback fired when the selected option changes.
	 */
	onChange?: (value: string) => void;
	/**
	 * Array of button options — must be between 2 and 6 options. Each option may
	 * include an optional icon or spinner before the label and a tally after it.
	 */
	options: OptionType[];
	/**
	 * Size of the segmented button: `'s'` (20px), `'m'` (24px, default), or
	 * `'l'` (32px). The icon scales with the size.
	 */
	size?: SegmentedButtonSize;
	/**
	 * Controlled value. Cannot be used together with `defaultValue`.
	 */
	value?: string;
}

/**
 * SegmentedButton UI component
 */
export const SegmentedButton = ({
	border = false,
	className,
	defaultValue,
	disabled = false,
	iconOnly = false,
	id,
	label,
	onChange,
	options,
	size = 'm',
	value,
	...props
}: SegmentedButtonProps) => {
	const baseClass = 'pds-segmented-button';
	const sizeClass = size !== 'm' ? `${baseClass}--${size}` : null;
	const borderClass = border ? `${baseClass}--bordered` : null;
	const iconOnlyClass = iconOnly ? `${baseClass}--icon-only` : null;

	// Development warning: icon-only requires an icon on every option.
	if (iconOnly && process.env.NODE_ENV !== 'production') {
		const missingIcon = options.some((option) => !option.iconName);
		if (missingIcon) {
			console.warn(
				'[SegmentedButton] `iconOnly` mode requires every option to have an `iconName`. Options without one will render an empty segment.',
			);
		}
	}

	const isControlled = typeof value !== 'undefined';
	const hasDefaultValue = typeof defaultValue !== 'undefined';

	const [internalValue, setInternalValue] = useState(
		hasDefaultValue ? defaultValue : '',
	);

	const handleSelection = (e: HandleSelectionEvent) => {
		setInternalValue(e.target.value);
		onChange?.(e.target.value);
	};

	if (options.length < 2 || options.length > 6) {
		return null;
	}

	return (
		<fieldset
			className={mergeClasses([
				baseClass,
				sizeClass,
				borderClass,
				iconOnlyClass,
				className ?? '',
			])}
			{...props}
		>
			<legend className='visually-hidden'>{label}</legend>

			<div className={`${baseClass}__track`}>
				{options.map((option, idx) => {
					const isChecked = isControlled
						? value === option.value
						: internalValue === option.value;
					const isDisabled = disabled || !!option.disabled;
					const optionId = option.id ?? `${id}-option-${idx}`;

					// In icon-only mode, show the label in a tooltip (like IconButton) instead of
					// the native title attribute. Fall back to the title attribute when disabled.
					const withTooltip = iconOnly && !isDisabled;

					const segmentContent = (
						<>
							{option.isLoading && (
								<Spinner
									isInline
									className={`${baseClass}__spinner`}
									color='currentColor'
									size='m'
								/>
							)}
							{option.iconName && !option.isLoading && (
								<Icon
									className={`${baseClass}__icon`}
									iconName={option.iconName}
								/>
							)}
							<span
								className={mergeClasses([
									`${baseClass}__label-text`,
									iconOnly ? 'visually-hidden' : null,
								])}
							>
								{option.label}
							</span>
							{option.tally && (
								<Tally
									className={`${baseClass}__tally`}
									label={option.tally.label}
									size='s'
									type={option.tally.type}
								/>
							)}
						</>
					);

					return (
						<div
							key={optionId}
							className={mergeClasses([
								`${baseClass}__option`,
								isChecked ? `${baseClass}__option--checked` : null,
								isDisabled ? `${baseClass}__option--disabled` : null,
							])}
						>
							<input
								checked={isChecked}
								className='visually-hidden'
								disabled={isDisabled}
								id={optionId}
								name={id}
								onChange={handleSelection}
								type='radio'
								value={option.value}
							/>
							<label
								htmlFor={optionId}
								title={withTooltip ? undefined : option.label}
							>
								{withTooltip ? (
									<Tooltip
										className={`${baseClass}__tooltip`}
										content={option.label}
										customTrigger={segmentContent}
										offsetValue={8}
									/>
								) : (
									segmentContent
								)}
							</label>
						</div>
					);
				})}
			</div>
		</fieldset>
	);
};
