import React, { ComponentPropsWithoutRef, CSSProperties } from 'react';

import {
	SPACING_2XL,
	SPACING_3XL,
	SPACING_4XL,
	SPACING_5XL,
	SPACING_6XL,
	SPACING_L,
	SPACING_M,
	SPACING_S,
	SPACING_XL,
	SPACING_XS,
} from '@pantheon-systems/pds-design-tokens/build/js/variables.global.js';
import {
	TYPOGRAPHY_SIZE_M,
	TYPOGRAPHY_SIZE_S,
	TYPOGRAPHY_SIZE_XS,
} from '@pantheon-systems/pds-design-tokens/build/js/variables.typography.js';

import { mergeClasses } from '@libs/components/utils';

import { HiddenLabel } from '@components/inputs/input-utilities';

export type SpinnerSize =
	| 's'
	| 'm'
	| 'l'
	| 'xl'
	| '2xl'
	| '3xl'
	| '4xl'
	| '5xl'
	| '6xl';

import './spinner.css';

export interface SpinnerProps extends ComponentPropsWithoutRef<'span'> {
	/**
	 * Additional class names
	 */
	className?: string;
	/**
	 * Arc color. Accepts any CSS color value or `var(--token)` reference.
	 * The track ring renders at the same color with reduced opacity.
	 * Defaults to the interactive blue token.
	 */
	color?: string;
	/**
	 * Should the spinner be an inline element? If true, it will be displayed inline-block without a visible label.
	 */
	isInline?: boolean;
	/**
	 * Spinner label. Will be displayed below the Spinner if `showLabel` is true.
	 */
	label?: string;
	/**
	 * Should the label be visible? If false, it will render for screen readers only.
	 */
	showLabel?: boolean;
	/**
	 * Spinner size
	 */
	size?: SpinnerSize;
}

// Size mapping for spinner dimensions
const spinnerSizes: Record<SpinnerSize, string> = {
	s: SPACING_S,
	m: SPACING_M,
	l: SPACING_L,
	xl: SPACING_XL,
	'2xl': SPACING_2XL,
	'3xl': SPACING_3XL,
	'4xl': SPACING_4XL,
	'5xl': SPACING_5XL,
	'6xl': SPACING_6XL,
};

// Font size mapping for labels
const labelFontSizes: Record<SpinnerSize, string> = {
	s: TYPOGRAPHY_SIZE_XS,
	m: TYPOGRAPHY_SIZE_XS,
	l: TYPOGRAPHY_SIZE_XS,
	xl: TYPOGRAPHY_SIZE_XS,
	'2xl': TYPOGRAPHY_SIZE_XS,
	'3xl': TYPOGRAPHY_SIZE_S,
	'4xl': TYPOGRAPHY_SIZE_S,
	'5xl': TYPOGRAPHY_SIZE_M,
	'6xl': TYPOGRAPHY_SIZE_M,
};

// Label margin mapping
const labelMargins: Record<SpinnerSize, string> = {
	s: SPACING_XS,
	m: SPACING_XS,
	l: SPACING_XS,
	xl: SPACING_XS,
	'2xl': SPACING_XS,
	'3xl': SPACING_S,
	'4xl': SPACING_S,
	'5xl': SPACING_M,
	'6xl': SPACING_L,
};

/**
 * Spinner UI component
 */
export const Spinner = ({
	className = '',
	color,
	isInline = false,
	label = 'Loading',
	showLabel = false,
	size = '3xl',
	...props
}: SpinnerProps) => {
	// Set up classes.
	const baseClass = 'pds-spinner';
	const displayClass = isInline ? `${baseClass}--inline` : null;

	// Get size values
	const spinnerSize = spinnerSizes[size];
	const fontSize = labelFontSizes[size];
	const labelMargin = labelMargins[size];

	// Create inline styles for sizing and optional color override
	const spinnerStyles = {
		'--spinner-size': spinnerSize,
		...(color ? { '--spinner-color': color } : {}),
	} as CSSProperties;

	const labelStyles = {
		fontSize: fontSize,
		marginBlockStart: labelMargin,
	} as CSSProperties;

	// Render the output
	return (
		<span
			aria-hidden='true'
			className={mergeClasses([baseClass, displayClass, className])}
			role='status'
			style={spinnerStyles}
			{...props}
		>
			<svg
				aria-hidden='true'
				className={`${baseClass}__icon`}
				viewBox='0 0 24 24'
				xmlns='http://www.w3.org/2000/svg'
			>
				<circle className={`${baseClass}__track`} cx='12' cy='12' r='9' />
				<g className={`${baseClass}__rotator`}>
					<circle className={`${baseClass}__arc`} cx='12' cy='12' r='9' />
				</g>
			</svg>
			{showLabel && !isInline ? (
				<span className={`${baseClass}__label`} style={labelStyles}>
					{label}
				</span>
			) : (
				<HiddenLabel label={label} />
			)}
		</span>
	);
};
