import React, {
	ChangeEvent,
	ComponentPropsWithoutRef,
	FocusEvent,
	forwardRef,
	ReactNode,
	Ref,
	useState,
} from 'react';

import { mergeClasses } from '@libs/components/utils';
import { ValidationStatus } from '@libs/types/input-types';

import { Icon } from '@components/icons/Icon/Icon';

import {
	CharacterCounter,
	ClearButton,
	getInputWidthStyle,
	inputCommonClasses,
	InputLabel,
	InputMessage,
	InputPrefix,
	PrefixVariants,
	SearchShortcut,
	stripUrlProtocol,
} from '../input-utilities';

import './text-input.css';

// Label strings type.
type LabelStrings = {
	clearButton: string;
	counterOverLimit?: string;
	searchShortcut: string;
	visibilityStatus: string;
	visibilityToggleHide: string;
	visibilityToggleShow: string;
};

type HtmlInputTypes =
	'text' | 'number' | 'email' | 'password' | 'tel' | 'time' | 'url' | 'search';

/**
 * Prop types for TextInput
 */
export interface TextInputProps extends ComponentPropsWithoutRef<'div'> {
	/**
	 * Auto complete attribute for the input field. The attribute value is either the keyword `off` or `on`, or an ordered list of space-separated tokens. Password fields are automatically off.
	 */
	autoComplete?: string;
	/**
	 * Additional class names for input.
	 */
	className?: string;
	/**
	 * Maximum character count for the character counter. Leave blank for no counter. Not valid for type `password`.
	 */
	counterMaxLength?: number;
	/**
	 * Initial value for the input field. Setting this prop automatically makes the input uncontrolled. Cannot be used in conjunction with the `value` prop.
	 */
	defaultValue?: string;
	/**
	 * Is the field disabled?
	 */
	disabled?: boolean;
	/**
	 * Does the input contain a clear button?
	 */
	hasClearButton?: boolean;
	/**
	 * Does the input contain the search shortcut?
	 * Only valid if the input type is `search`.
	 */
	hasSearchShortcut?: boolean;
	/**
	 * Show a fixed "https://" prefix for URL inputs. Only valid if the input type is "url".
	 */
	hasUrlPrefix?: boolean;
	/**
	 * Input ID.
	 */
	id: string;
	/**
	 * Additional props for the `<input>` element.
	 */
	inputProps?: ComponentPropsWithoutRef<'input'>;
	/**
	 * Width of the input field in pixels. When omitted, the input fills its container.
	 */
	inputWidth?: number;
	/**
	 * Input label.
	 */
	label: string;
	/**
	 * Input message. Used to provide supplemental text. Will be displayed below the input field.
	 */
	message?: string | ReactNode;
	/**
	 * onBlur event handler.
	 */
	onBlur?: (e: FocusEvent<HTMLInputElement>) => void;
	/**
	 * onChange event handler. Controlled inputs should use this to manage the input value. Uncontrolled inputs will manage their own state, but may still use this to access the event object.
	 */
	onChange?: (e: ChangeEvent<HTMLInputElement>) => void;
	/**
	 * Function to clear the input field. Only necessary if the input is controlled. This functionality is built-in for uncontrolled inputs.
	 */
	onClear?: () => void;
	/**
	 * onFocus event handler.
	 */
	onFocus?: (e: FocusEvent<HTMLInputElement>) => void;
	/**
	 * Optional placeholder text to display when the input field is empty.
	 */
	placeholder?: string;
	/**
	 * Is the field read-only?
	 */
	readonly?: boolean;
	/**
	 * Is this field required?
	 */
	required?: boolean;
	/**
	 * Icon to use when type is search.
	 */
	searchIcon?: 'search' | 'filter';
	/**
	 * Should the label be visible? If false, it will render for screen readers only.
	 */
	showLabel?: boolean;
	/**
	 * Show Toggle visibility control for input. Valid for type `password` only.
	 */
	showVisibilityToggle?: boolean;
	/**
	 * Input size.
	 */
	size?: 's' | 'm';
	/**
	 * Optional tooltip text to display additional information.
	 */
	tooltipText?: string | null;
	/**
	 * Translation strings for various labels or other visually-hidden text.
	 */
	translationStrings?: LabelStrings;
	/**
	 * Type of input field to use. For `time`, prefer the Timepicker component when possible — it offers segmented entry, 12/24-hour display, and timezone support. Use TextInput's native `time` type only as a lightweight fallback where that complexity isn't warranted; note it renders with browser-native time picker UI that isn't fully styleable to match PDS.
	 */
	type?: HtmlInputTypes;
	/**
	 * Validation message for the input field based on the validation status.
	 */
	validationMessage?: string;
	/**
	 * Validation status of the input field.
	 */
	validationStatus?: ValidationStatus;
	/**
	 * Value of the input field. Used to set the value of the input field when controlled. Cannot be used in conjunction with the `defaultValue` prop.
	 */
	value?: string;
}

/**
 * URL Prefix component for TextInput
 */
const UrlPrefix = () => (
	<div className='pds-text-input__url-prefix'>https://</div>
);

/**
 * TextInput UI component
 */
export const TextInput = forwardRef(
	(
		{
			autoComplete,
			className,
			counterMaxLength,
			defaultValue,
			disabled = false,
			hasClearButton = false,
			hasSearchShortcut = false,
			hasUrlPrefix = false,
			id,
			inputProps,
			inputWidth,
			label,
			message,
			onBlur,
			onChange,
			onClear,
			onFocus,
			placeholder,
			readonly = false,
			required = false,
			searchIcon = 'search',
			showLabel = true,
			showVisibilityToggle = false,
			size = 's',
			tooltipText = null,
			translationStrings = {
				clearButton: 'Clear input text',
				counterOverLimit: 'Character limit exceeded by',
				searchShortcut: 'Press / to focus the search field',
				visibilityStatus: 'The value of the input is',
				visibilityToggleHide: 'Hide input value',
				visibilityToggleShow: 'Show input value',
			},
			type = 'text',
			validationMessage,
			validationStatus,
			value,
			...props
		}: TextInputProps,
		ref: Ref<HTMLInputElement>,
	) => {
		// Determine input width style.
		const inputWidthStyle = getInputWidthStyle(inputWidth);

		// Set up classes.
		const baseClass = 'pds-text-input';
		const disabledClass = disabled ? inputCommonClasses.disabled : null;
		const requiredClass =
			required && !disabled ? inputCommonClasses.required : null;
		const errorClass =
			validationStatus === 'error' ? inputCommonClasses.error : null;
		const successClass =
			validationStatus === 'success' ? inputCommonClasses.success : null;
		const readonlyClass = readonly ? inputCommonClasses.readonly : null;
		const sizeClass = size !== 's' ? `${baseClass}--${size}` : null;
		const urlPrefixClass =
			hasUrlPrefix && type === 'url' ? `${baseClass}--has-url-prefix` : null;

		// Set prefix.
		let prefix: PrefixVariants | null = null;
		if (type === 'search') {
			prefix = 'search';
		}

		if (type === 'search' && searchIcon === 'filter') {
			prefix = 'filter';
		}

		if (validationStatus === 'error') {
			prefix = 'error';
		}
		if (validationStatus === 'success') {
			prefix = 'success';
		}

		// If there is a validation message, use that. Otherwise, use the message prop.
		const processedMessage = validationMessage || message;

		// Determine if the input is controlled.
		const isControlled = typeof value != 'undefined';

		// When a component is not controlled, it can have a defaultValue.
		const hasDefaultValue = typeof defaultValue != 'undefined';

		// If the input is uncontrolled, use state within the component to manage the value.
		const [internalValue, setInternalValue] = useState(
			hasDefaultValue ? defaultValue : '',
		);

		// Determine if the input has a value either from props or internal state.
		const hasValue = value || internalValue;

		// Handle blur event.
		const handleBlur = (e: FocusEvent<HTMLInputElement>) => {
			if (showVisibilityToggle && visibility) {
				setVisibility(false);
			}

			// Process URL prefix if needed
			if (hasUrlPrefix && type === 'url') {
				const processedValue = stripUrlProtocol(e.target.value);

				const newEvent = {
					...e,
					target: {
						...e.target,
						value: processedValue,
					},
				} as FocusEvent<HTMLInputElement>;

				if (onBlur) {
					onBlur(newEvent);
				}
			} else if (onBlur) {
				onBlur(e);
			}
		};

		// Handle change event.
		const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
			if (hasUrlPrefix && type === 'url') {
				const processedValue = stripUrlProtocol(e.target.value);

				const newEvent = {
					...e,
					target: {
						...e.target,
						value: processedValue,
					},
				} as ChangeEvent<HTMLInputElement>;

				if (!isControlled) {
					setInternalValue(processedValue);
				}

				if (onChange) {
					onChange(newEvent);
				}
			} else {
				if (!isControlled) {
					setInternalValue(e.target.value);
				}

				if (onChange) {
					onChange(e);
				}
			}
		};

		// Handle clear button.
		const handleClear = () => {
			if (!isControlled) {
				setInternalValue('');
			}

			if (onClear) {
				onClear();
			}

			// Set focus to the input field.
			const element = document.getElementById(id);
			if (element) {
				element.focus();
			}
		};

		// Set up state for visibility.
		const [visibility, setVisibility] = useState(false);

		// Function to toggle visibility.
		const handleShowVisibilityToggle = () => {
			// Toggle visibility.
			setVisibility((previous) => {
				return !previous;
			});

			// Set focus to the input field.
			const element = document.getElementById(id);
			if (element) {
				element.focus();
			}
		};

		// Get input type from props.
		let processedType = type;

		// Toggle input type between `password` and `text`.
		if (showVisibilityToggle && type === 'password') {
			if (visibility) {
				processedType = 'text';
			} else {
				processedType = 'password';
			}
		}

		// Render the output
		return (
			<div
				className={mergeClasses([
					inputCommonClasses.base,
					baseClass,
					sizeClass,
					disabledClass,
					requiredClass,
					errorClass,
					successClass,
					readonlyClass,
					urlPrefixClass,
					className ?? '',
				])}
				style={inputWidth ? inputWidthStyle : null}
				{...props}
			>
				<InputLabel
					disabled={disabled}
					id={id}
					label={label}
					required={required}
					showLabel={showLabel}
					tooltipText={tooltipText}
				/>

				{/* Visually-hidden message for visibility status */}
				{showVisibilityToggle && type === 'password' && (
					<div aria-live='polite' className='visually-hidden'>
						{`${translationStrings.visibilityStatus} ${
							visibility ? 'visible' : 'hidden'
						}.`}
					</div>
				)}

				<div
					className={`${baseClass}__input-wrapper ${hasUrlPrefix && type === 'url' ? `${baseClass}__input-wrapper--has-prefix` : ''}`}
				>
					{prefix && <InputPrefix variant={prefix} />}

					{hasUrlPrefix && type === 'url' && <UrlPrefix />}

					<input
						ref={ref}
						aria-describedby={processedMessage ? `${id}__message` : null}
						aria-invalid={validationStatus === 'error' ? true : null}
						autoComplete={type === 'password' ? 'off' : autoComplete}
						className={`${baseClass}__input ${hasUrlPrefix && type === 'url' ? `${baseClass}__input--has-prefix` : ''}`}
						disabled={disabled}
						id={id}
						name={id}
						onBlur={handleBlur}
						onChange={handleChange}
						onFocus={onFocus}
						placeholder={placeholder}
						readOnly={readonly}
						required={required}
						type={processedType}
						value={isControlled ? value : internalValue}
						{...inputProps}
					/>

					{/* Clear button */}
					{hasClearButton && hasValue && (
						<ClearButton
							clearLabel={translationStrings.clearButton}
							handleClearInput={handleClear}
							id={id}
						/>
					)}

					{/* Visibility toggle button */}
					{showVisibilityToggle && type === 'password' && (
						<button
							aria-controls={id}
							className={`${baseClass}__visibility-toggle`}
							onClick={handleShowVisibilityToggle}
							onMouseDown={(e) => e.preventDefault()}
							title={
								visibility
									? translationStrings.visibilityToggleHide
									: translationStrings.visibilityToggleShow
							}
							type='button'
						>
							<Icon iconName={visibility ? 'eyeSlash' : 'eye'} size='m' />
						</button>
					)}

					{/* Search shortcut */}
					{hasSearchShortcut && type === 'search' && !hasValue && (
						<SearchShortcut
							inputId={id}
							shortcutLabel={translationStrings.searchShortcut}
						/>
					)}

					{/* Character counter */}
					{counterMaxLength && type !== 'password' && (
						<CharacterCounter
							currentLength={hasValue.length}
							id={id}
							maxLength={counterMaxLength}
							overLimitMessage={translationStrings.counterOverLimit}
						/>
					)}
				</div>

				{processedMessage && (
					<InputMessage
						hasValidationMessage={validationMessage ? true : false}
						id={id}
						message={processedMessage}
						validationMessageHasDecorators={false}
						validationStatus={validationStatus}
					/>
				)}
			</div>
		);
	},
);
